from array import array

def product_of_second_values(pairs):
    """
    Calculate the product of the second values in an iterable of tuples/sequences.
    Returns an array('d') with one element (the product).
    If 'pairs' is empty the product is 1.0 (empty product).
    Raises TypeError/ValueError for invalid input.

    Example:
      product_of_second_values([(1, 2), (3, 4.5)]) -> array('d', [9.0])
    """
    try:
        iterator = iter(pairs)
    except TypeError:
        raise TypeError("pairs must be an iterable of tuples/sequences")

    prod = 1.0
    for idx, item in enumerate(pairs):
        try:
            val = item[1]
        except Exception:
            raise ValueError(f"item at index {idx} does not have a second element")
        try:
            num = float(val)
        except Exception:
            raise TypeError(f"second value at index {idx} is not numeric: {val!r}")
        prod *= num

    return array('d', [prod])

