import socket
import json
import urllib.request
import urllib.error
import urllib.parse

def resolve_and_geolocate(host: str, timeout: float = 5.0, ipinfo_token: str | None = None) -> dict:
    """
    Resolve `host` to an IP address and fetch geolocation info from ipinfo.io.

    Returns a dictionary with these keys on success:
      - "host": the input host
      - "ip": resolved IP address (string)
      - "geo": parsed JSON response from ipinfo.io (dict)
      - "ok": True

    On failure, returns a dictionary with:
      - "host": the input host
      - "ok": False
      - "error": human-readable error message
      - optionally "details": extra error info (e.g. HTTP status, response body)

    Parameters:
      - host: hostname or IP to resolve
      - timeout: seconds for network operations (DNS + HTTP)
      - ipinfo_token: optional ipinfo.io token (if you have one). If provided, it will be sent as ?token=...

    This function uses only Python's standard library (no external deps).
    """
    if not host or not isinstance(host, str):
        return {"host": host, "ok": False, "error": "empty or invalid host"}

    # 1) Resolve hostname to IP (prefer first returned address)
    try:
        infos = socket.getaddrinfo(host, None)
        if not infos:
            return {"host": host, "ok": False, "error": "DNS lookup returned no addresses"}
        # sockaddr: tuple whose first element is the IP string
        sockaddr = infos[0][4]
        ip = sockaddr[0]
    except socket.gaierror as e:
        return {"host": host, "ok": False, "error": "DNS resolution failed", "details": str(e)}
    except Exception as e:
        return {"host": host, "ok": False, "error": "Unexpected error during DNS resolution", "details": str(e)}

    # 2) Query ipinfo.io for geolocation
    base_url = f"https://ipinfo.io/{urllib.parse.quote(ip)}/json"
    if ipinfo_token:
        base_url += "?token=" + urllib.parse.quote(ipinfo_token)

    req = urllib.request.Request(base_url, headers={"User-Agent": "resolve-and-geolocate/1.0"})

    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            body = resp.read()
            try:
                data = json.loads(body.decode("utf-8", errors="replace"))
            except json.JSONDecodeError:
                return {
                    "host": host,
                    "ip": ip,
                    "ok": False,
                    "error": "Failed to decode JSON from ipinfo.io",
                    "details": body.decode("utf-8", errors="replace"),
                }
    except urllib.error.HTTPError as e:
        # Try to read response body for more context
        try:
            err_body = e.read().decode("utf-8", errors="replace")
        except Exception:
            err_body = None
        return {
            "host": host,
            "ip": ip,
            "ok": False,
            "error": f"HTTP error contacting ipinfo.io (status {e.code})",
            "details": err_body,
        }
    except urllib.error.URLError as e:
        return {"host": host, "ip": ip, "ok": False, "error": "Network error contacting ipinfo.io", "details": str(e)}
    except Exception as e:
        return {"host": host, "ip": ip, "ok": False, "error": "Unexpected error contacting ipinfo.io", "details": str(e)}

    # Success
    return {"host": host, "ip": ip, "geo": data, "ok": True}


