Here's a single, self-contained Python function that resolves a hostname (or accepts an IP) and fetches geolocation info from ipinfo.io, with robust error handling. It uses the lightweight requests library.

```python
import socket
import ipaddress
import requests
from urllib.parse import urlparse
from typing import Optional, Dict, Any


def resolve_and_geolocate(host: str,
                          timeout: float = 5.0,
                          ipinfo_token: Optional[str] = None,
                          prefer_ipv4: bool = True) -> Dict[str, Any]:
    """
    Resolve the given host (or accept an IP) to an IP address and fetch geolocation
    information from ipinfo.io.

    Parameters:
    - host: hostname, domain, bare IP, or URL (e.g. "example.com", "8.8.8.8", "https://example.com/path")
    - timeout: timeout in seconds for the HTTP request to ipinfo.io
    - ipinfo_token: optional ipinfo.io token to include as ?token=TOKEN (if you have one)
    - prefer_ipv4: whether to prefer IPv4 addresses when resolving (defaults to True)

    Returns:
    - On success: dict with "success": True, "ip": <resolved IP>, "hostname": <original hostname parsed>,
      "raw": <full JSON response from ipinfo.io>, and "location": {latitude, longitude} where available.
    - On failure: dict with "success": False and "error": human-readable message plus optional "details".

    Requirements:
    - requests library (pip install requests)
    """
    # Normalize and extract hostname (handles inputs like URLs or host:port)
    try:
        parsed = urlparse(host if '://' in host else '//' + host)
        hostname = parsed.hostname or host
    except Exception:
        hostname = host

    # If hostname is empty after parsing, bail out
    if not hostname:
        return {"success": False, "error": "No hostname found in input."}

    # If the input is already an IP, validate and use it directly
    try:
        ip_obj = ipaddress.ip_address(hostname)
        ip_str = str(ip_obj)
    except ValueError:
        # Not an IP string — resolve DNS
        try:
            # getaddrinfo may return multiple addresses; prefer IPv4/IPv6 as requested
            addrinfo = socket.getaddrinfo(hostname, None, family=socket.AF_UNSPEC, type=socket.SOCK_STREAM)
            if not addrinfo:
                return {"success": False, "error": "DNS resolution returned no addresses.", "details": hostname}

            selected_ip = None
            # Try to honor prefer_ipv4
            if prefer_ipv4:
                for ai in addrinfo:
                    if ai[0] == socket.AF_INET:
                        selected_ip = ai[4][0]
                        break
            else:
                for ai in addrinfo:
                    if ai[0] == socket.AF_INET6:
                        selected_ip = ai[4][0]
                        break
            # If not found preferred family, take first available
            if not selected_ip:
                selected_ip = addrinfo[0][4][0]

            ip_str = selected_ip
        except socket.gaierror as e:
            return {"success": False, "error": "DNS resolution failed.", "details": str(e)}
        except Exception as e:
            return {"success": False, "error": "Unexpected error during DNS resolution.", "details": str(e)}

    # Build ipinfo URL
    base_url = f"https://ipinfo.io/{ip_str}/json"
    if ipinfo_token:
        url = f"{base_url}?token={ipinfo_token}"
    else:
        url = base_url

    # Query ipinfo.io
    try:
        headers = {"User-Agent": "resolve_and_geolocate/1.0"}
        resp = requests.get(url, timeout=timeout, headers=headers)
    except requests.exceptions.Timeout:
        return {"success": False, "error": "Request to ipinfo.io timed out."}
    except requests.exceptions.ConnectionError as e:
        return {"success": False, "error": "Network error while contacting ipinfo.io.", "details": str(e)}
    except requests.exceptions.RequestException as e:
        return {"success": False, "error": "HTTP request error while contacting ipinfo.io.", "details": str(e)}

    # Handle non-OK responses
    if resp.status_code != 200:
        # Try to extract error message from JSON body if present
        try:
            body = resp.json()
        except Exception:
            body = resp.text
        return {
            "success": False,
            "error": f"ipinfo.io returned status {resp.status_code}.",
            "details": body
        }

    # Parse JSON
    try:
        data = resp.json()
    except ValueError as e:
        return {"success": False, "error": "Failed to decode JSON from ipinfo.io.", "details": str(e)}

    # Optionally parse latitude/longitude from 'loc' field
    location = None
    loc = data.get("loc")
    if isinstance(loc, str):
        try:
            lat_str, lon_str = loc.split(",", 1)
            location = {"latitude": float(lat_str.strip()), "longitude": float(lon_str.strip())}
        except Exception:
            location = None

    result = {
        "success": True,
        "ip": ip_str,
        "hostname": hostname,
        "raw": data,
    }
    if location:
        result["location"] = location

    # Include some convenient top-level fields if present
    for k in ("city", "region", "country", "org", "postal", "timezone"):
        if k in data:
            result[k] = data[k]

    return result
