from typing import Dict, Any, List, Optional
import random

def veg_statistics(people_to_veg: Dict[str, Any], seed: Optional[int] = None) -> Dict[str, Any]:
    """
    Reverse a mapping of people -> vegetable(s) to vegetable -> people, assign random counts (1-10)
    to each vegetable, and compute each vegetable's percentage of the total counts.

    Args:
        people_to_veg: dict mapping person -> vegetable (str) or person -> list/tuple of vegetables.
        seed: optional int seed for reproducible random choices/counts.

    Returns:
        dict with keys:
            - 'veg_to_people': Dict[str, List[str]] mapping vegetable -> list of people who prefer it
            - 'veg_to_person': Dict[str, str] mapping vegetable -> one chosen person who prefers it
            - 'counts': Dict[str, int] random count assigned to each vegetable (1..10)
            - 'percentages': Dict[str, float] percentage of total counts for each vegetable (rounded to 2 dp)
            - 'total': int total of all counts
    """
    if seed is not None:
        random.seed(seed)

    # Build veg -> list of people
    veg_to_people: Dict[str, List[str]] = {}
    for person, vegs in people_to_veg.items():
        # allow single string or an iterable of vegs (list/tuple)
        if isinstance(vegs, (list, tuple, set)):
            items = list(vegs)
        else:
            items = [vegs]
        for veg in items:
            # normalize to string
            veg_str = str(veg)
            veg_to_people.setdefault(veg_str, []).append(person)

    # Assign a random count (1..10) to each vegetable
    counts: Dict[str, int] = {}
    for veg in veg_to_people:
        counts[veg] = random.randint(1, 10)

    total = sum(counts.values())

    # Compute percentages safely (avoid division by zero)
    if total > 0:
        percentages = {veg: round(count / total * 100, 2) for veg, count in counts.items()}
    else:
        percentages = {veg: 0.0 for veg in counts}

    # Map each vegetable to one person who prefers it (choose randomly among those people)
    veg_to_person: Dict[str, str] = {}
    for veg, people in veg_to_people.items():
        if people:
            veg_to_person[veg] = random.choice(people)
