import random
from collections import defaultdict
from typing import Dict, Iterable, List, Union, Tuple

def vegetable_statistics(people_to_veg: Dict[str, Union[str, Iterable[str]]],
                         seed: int = None
                        ) -> Dict[str, Dict]:
    """
    Reverse a mapping of people -> vegetables, assign random counts to each vegetable,
    and compute each vegetable's share (percentage) of the total counts.

    Parameters:
    - people_to_veg: dict where keys are person names and values are either a single
      vegetable (str) or an iterable of vegetables (list/tuple/set).
    - seed: optional int to seed the random generator for reproducible results.

    Returns:
    A dict with these keys:
    - "veg_to_people": {vegetable: [person, ...], ...}
    - "veg_counts": {vegetable: int_count, ...}      # random ints 1..10
    - "veg_percentages": {vegetable: float_percent, ...}  # percentages summing to 100.0
    - "total_count": int  # sum of all random counts

    Example:
    >>> people = {"Alice": ["carrot", "pea"], "Bob": "carrot", "Eve": ["spinach"]}
    >>> vegetable_statistics(people, seed=1)
    {
      'veg_to_people': {'carrot': ['Alice', 'Bob'], 'pea': ['Alice'], 'spinach': ['Eve']},
      'veg_counts': {'carrot': 3, 'pea': 10, 'spinach': 2},
      'veg_percentages': {'carrot': 20.0, 'pea': 66.66666666666666, 'spinach': 13.333333333333334},
      'total_count': 15
    }
    """
    if seed is not None:
        random.seed(seed)

    veg_to_people: Dict[str, List[str]] = defaultdict(list)

    for person, vegs in people_to_veg.items():
        # Normalize single-string value to an iterable of one element
        if isinstance(te := vegs, str):
            iterable = (te,)
        else:
            iterable = vegs  # assume it's iterable of strings
        for v in iterable:
            veg_to_people[v].append(person)

    # Assign random counts to each vegetable (1..10)
    veg_counts: Dict[str, int] = {v: random.randint(1, 10) for v in veg_to_people}
    total = sum(veg_counts.values())

    # Avoid division by zero for empty input
    if total == 0:
        veg_percentages: Dict[str, float] = {v: 0.0 for v in veg_counts}
    else:
        veg_percentages = {v: (count / total) * 100.0 for v, count in veg_counts.items()}

    return {
        "veg_to_people": dict(veg_to_people),
        "veg_counts": veg_counts,
        "veg_percentages": veg_percentages,
        "total_count": total,
    }
