def grade_report(data, decimal_places=2, use_tabulate=True):
    """
    Create a report on students' grades across subjects and calculate averages.

    Parameters:
    - data: input data in one of these forms:
        1) list of (student, subject, score) tuples/lists, e.g.
           [("Alice", "Math", 90), ("Alice", "Math", 85), ("Bob", "Sci", 78)]
        2) dict mapping student -> dict mapping subject -> score or list of scores, e.g.
           {"Alice": {"Math": [90,85], "Eng": 88}, "Bob": {"Math": 75}}
    - decimal_places: number of decimals to show for averages (default 2)
    - use_tabulate: if True and the 'tabulate' package is installed, use it for nicer table formatting

    Returns:
    - A dict with these keys:
      - "cell_averages": nested dict student -> subject -> avg_score
      - "student_averages": dict student -> avg_score (across all their subjects)
      - "subject_averages": dict subject -> avg_score (across all students)
      - "table": a string with a formatted table (also printed)
    """
    from collections import defaultdict
    from statistics import mean

    # Normalize input into student -> subject -> list of scores
    ss_scores = defaultdict(lambda: defaultdict(list))

    if isinstance(data, dict):
        # data: student -> subject -> score/list
        for student, subj_map in data.items():
            if subj_map is None:
                continue
            for subject, val in subj_map.items():
                if val is None:
                    continue
                if isinstance(val, (list, tuple)):
                    for v in val:
                        try:
                            ss_scores[student][subject].append(float(v))
                        except Exception:
                            pass
                else:
                    try:
                        ss_scores[student][subject].append(float(val))
                    except Exception:
                        pass
    else:
        # assume iterable of (student, subject, score)
        for entry in data:
            if not entry:
                continue
            if len(entry) < 3:
                continue
            student, subject, score = entry[0], entry[1], entry[2]
            try:
                ss_scores[student][subject].append(float(score))
            except Exception:
                pass

    # collect sorted students and subjects
    students = sorted(ss_scores.keys())
    subjects = sorted({s for student in students for s in ss_scores[student].keys()})

    # compute cell averages
    cell_averages = defaultdict(dict)
    for student in students:
        for subject in subjects:
            scores = ss_scores[student].get(subject, [])
            if scores:
                cell_averages[student][subject] = mean(scores)
            else:
                # leave absent as None
                cell_averages[student][subject] = None

    # compute student averages (average across all their scores)
    student_averages = {}
    for student in students:
        all_scores = []
        for subject in subjects:
            all_scores.extend(ss_scores[student].get(subject, []))
        if all_scores:
            student_averages[student] = mean(all_scores)
        else:
            student_averages[student] = None

    # compute subject averages (average across all students for each subject)
    subject_averages = {}
    for subject in subjects:
        all_scores = []
        for student in students:
            all_scores.extend(ss_scores[student].get(subject, []))
        if all_scores:
            subject_averages[subject] = mean(all_scores)
        else:
            subject_averages[subject] = None

    # build table rows: header, rows per student, final subject-average row
    header = ["Student"] + subjects + ["Average"]
    rows = []
    fmt = ("{:." + str(decimal_places) + "f}").format

    for student in students:
        row = [student]
        for subject in subjects:
            val = cell_averages[student][subject]
            row.append(fmt(val) if val is not None else "-")
        s_avg = student_averages[student]
        row.append(fmt(s_avg) if s_avg is not None else "-")
        rows.append(row)

    # final averages row
    avg_row = ["Average"]
    for subject in subjects:
        val = subject_averages.get(subject)
        avg_row.append(fmt(val) if val is not None else "-")
    # overall average (mean of all scores)
    overall_scores = []
    for student in students:
        for subject in subjects:
            overall_scores.extend(ss_scores[student].get(subject, []))
    overall_avg = mean(overall_scores) if overall_scores else None
    avg_row.append(fmt(overall_avg) if overall_avg is not None else "-")

    rows.append(avg_row)

    # Try to use tabulate if requested and available
    table_str = None
    if use_tabulate:
        try:
            from tabulate import tabulate
            table_str = tabulate(rows, headers=header, tablefmt="grid")
        except Exception:
            table_str = None

    # If tabulate not available or disabled, build a simple aligned text table
    if table_str is None:
        # determine column widths
        cols = [header] + rows
        col_widths = []
        for c in range(len(header)):
            width = max(len(str(row[c])) for row in cols)
            col_widths.append(width)
        # build a formatted string
        lines = []
        # header
        hdr = " | ".join(str(header[i]).ljust(col_widths[i]) for i in range(len(header)))
        sep = "-+-".join("-" * col_widths[i] for i in range(len(header)))
        lines.append(hdr)
        lines.append(sep)
        for r in rows:
            lines.append(" | ".join(str(r[i]).ljust(col_widths[i]) for i in range(len(header))))
        table_str = "\n".join(lines)

    # Print the table
    print(table_str)

    # Convert defaultdicts to normal dicts for return
    cell_averages = {stu: dict(cell_averages[stu]) for stu in cell_averages}
    return {
        "cell_averages": cell_averages,
        "student_averages": dict(student_averages),
        "subject_averages": dict(subject_averages),
        "table": table_str,
    }

