Here's a self-contained Python function that uses the lightweight openpyxl library to process all .xlsx files in a given directory (optionally recursively). It prefixes every double quote (") in text cell values with a double backslash (so " becomes \\"). It skips cells that look like formulas (values starting with '=') and optionally makes a backup of each modified file.

Prerequisite: install openpyxl if you don't have it:
pip install openpyxl

Function:

```python
import os
import shutil
from typing import Dict, Tuple
from openpyxl import load_workbook

def protect_quotes_in_xlsx_dir(directory: str, recursive: bool = False, backup: bool = True) -> Dict[str, Tuple[int, int]]:
    """
    For all .xlsx files in `directory` (recursively if recursive=True), prefix every double quote (")
    in text cell values with a double backslash so that each " becomes \\"
    Formula cells (values starting with '=') are skipped.

    Args:
        directory: path to directory containing .xlsx files.
        recursive: whether to search directories recursively.
        backup: whether to make a backup copy of each file before overwriting (adds `.bak` suffix).

    Returns:
        A dict mapping filepath -> (cells_changed, total_string_cells_checked)
    """
    results = {}

    if not os.path.isdir(directory):
        raise ValueError(f"Not a directory: {directory}")

    if recursive:
        walker = (os.path.join(root, name) for root, _, files in os.walk(directory) for name in files)
    else:
        walker = (os.path.join(directory, name) for name in os.listdir(directory))

    for path in walker:
        if not path.lower().endswith('.xlsx'):
            continue
        if not os.path.isfile(path):
            continue

        try:
            wb = load_workbook(path)
        except Exception as e:
            print(f"Skipping '{path}' — failed to open workbook: {e}")
            continue

        cells_changed = 0
        string_cells_checked = 0

        try:
            for ws in wb.worksheets:
                # iterate through all cells (not values_only so we can write back)
                for row in ws.iter_rows():
                    for cell in row:
                        val = cell.value
                        if isinstance(val, str):
                            string_cells_checked += 1
                            # Skip formulas (common representation is string starting with '=')
                            if val.startswith('='):
                                continue
                            if '"' in val:
                                # Replace each double quote " with two backslashes followed by a quote: \" => \\"
                                new_val = val.replace('"', '\\\\\"')
                                if new_val != val:
                                    cell.value = new_val
                                    cells_changed += 1
            if cells_changed > 0:
                if backup:
                    bak_path = path + '.bak'
                    try:
                        shutil.copy2(path, bak_path)
                    except Exception as e:
                        print(f"Warning: failed to create backup for '{path}': {e}")
                wb.save(path)
        except Exception as e:
            print(f"Error while processing '{path}': {e}")
        finally:
            try:
                wb.close()
            except Exception:
                pass

        results[path] = (cells_changed, string_cells_checked)

    return results
```

Example usage:
- protect_quotes_in_xlsx_dir('/path/to/folder')
- protect_quotes_in_xlsx_dir('/path/to/folder', recursive=True, backup=False)

The function returns a dict mapping each processed file path to a tuple (cells_changed, total_string_cells_checked).

Here's a single self-contained Python function that converts an Excel file (.xls or .xlsx/.xlsm) to a CSV file. It uses the lightweight csv module plus openpyxl for newer Excel files and xlrd for legacy .xls files. If the required library is missing, the function raises an informative ImportError telling you how to install it.

Paste this function into your script and call excel_to_csv(...).

```python
import os
import csv
import datetime

def excel_to_csv(src_path, dst_path=None, sheet_name=None, encoding='utf-8', delimiter=','):
    """
    Convert an Excel file (.xls or .xlsx/.xlsm) to a CSV file.

    Parameters:
    - src_path (str): Path to the source Excel file.
    - dst_path (str, optional): Path to the destination CSV file. If None, uses the same name as src_path with .csv extension.
    - sheet_name (str, optional): Name of the sheet to convert. If not provided, the first sheet is used.
    - encoding (str): Encoding for the output CSV file (default 'utf-8').
    - delimiter (str): Field delimiter for the CSV (default ',').

    Returns:
    - str: Path to the written CSV file.

    Raises:
    - FileNotFoundError: If src_path does not exist.
    - ValueError: If the file extension is unsupported or specified sheet is not found.
    - ImportError: If required dependency (openpyxl or xlrd) is missing for the file type.
    """
    if not os.path.isfile(src_path):
        raise FileNotFoundError(f"Source file not found: {src_path}")

    root, ext = os.path.splitext(src_path)
    ext = ext.lower()

    if dst_path is None:
        dst_path = root + '.csv'

    def _format_value(v):
        # Normalize values for CSV: convert datetimes to ISO, None -> empty string
        if v is None:
            return ''
        if isinstance(v, (datetime.datetime, datetime.date, datetime.time)):
            # datetime.time has no isoformat timezone in some Python versions; isoformat is fine
            return v.isoformat()
        return str(v)

    # Handle .xlsx/.xlsm/.xltx/.xltm with openpyxl
    if ext in ('.xlsx', '.xlsm', '.xltx', '.xltm'):
        try:
            import openpyxl
        except Exception as e:
            raise ImportError("openpyxl is required to read .xlsx/.xlsm files. Install with: pip install openpyxl") from e

        wb = openpyxl.load_workbook(filename=src_path, read_only=True, data_only=True)
        # choose sheet
        if sheet_name:
            if sheet_name not in wb.sheetnames:
                raise ValueError(f"Sheet '{sheet_name}' not found. Available sheets: {wb.sheetnames}")
            sheet = wb[sheet_name]
        else:
            sheet = wb[wb.sheetnames[0]]

        with open(dst_path, 'w', newline='', encoding=encoding) as csvfile:
            writer = csv.writer(csvfile, delimiter=delimiter)
            for row in sheet.iter_rows(values_only=True):
                writer.writerow([_format_value(cell) for cell in row])

        return dst_path

    # Handle old .xls with xlrd
    elif ext == '.xls':
        try:
            import xlrd
        except Exception as e:
            raise ImportError("xlrd is required to read .xls files. Install with: pip install xlrd") from e

        book = xlrd.open_workbook(src_path, on_demand=True)
        try:
            if sheet_name:
                try:
                    sheet = book.sheet_by_name(sheet_name)
                except xlrd.biffh.XLRDError:
                    raise ValueError(f"Sheet '{sheet_name}' not found. Available sheets: {book.sheet_names()}")
            else:
                sheet = book.sheet_by_index(0)

            with open(dst_path, 'w', newline='', encoding=encoding) as csvfile:
                writer = csv.writer(csvfile, delimiter=delimiter)
                for rx in range(sheet.nrows):
                    row_vals = []
                    for cx in range(sheet.ncols):
                        ctype = sheet.cell_type(rx, cx)
                        cval = sheet.cell_value(rx, cx)
                        if ctype == xlrd.XL_CELL_DATE:
                            try:
                                # convert Excel date to Python datetime
                                dt = xlrd.xldate.xldate_as_datetime(cval, book.datemode)
                                row_vals.append(_format_value(dt))
                            except Exception:
                                row_vals.append(_format_value(cval))
                        else:
                            row_vals.append(_format_value(cval))
                    writer.writerow(row_vals)
            return dst_path
        finally:
            try:
                book.release_resources()
            except Exception:
                pass

    else:
        raise ValueError(f"Unsupported file extension '{ext}'. Supported: .xls, .xlsx, .xlsm, .xltx, .xltm")
```

