def excel_to_csv(src_path, dst_path=None, sheet_index=0, encoding='utf-8-sig', delimiter=','):
    """
    Convert the first (or specified) sheet of an Excel file (.xls, .xlsx, .xlsm) to a CSV file.
    - src_path: path to the Excel file.
    - dst_path: path to the resulting CSV file. If None, uses same directory/name with .csv extension.
    - sheet_index: zero-based index of the sheet to export (default 0).
    - encoding: file encoding for output CSV (default 'utf-8-sig' to help Excel on Windows).
    - delimiter: CSV delimiter (default ',').

    Returns the path to the written CSV file.

    Requires:
    - openpyxl for .xlsx/.xlsm (install with `pip install openpyxl`)
    - xlrd for .xls (install with `pip install xlrd`)
    """
    import os
    import csv
    import datetime

    if not os.path.isfile(src_path):
        raise FileNotFoundError(f"Source file not found: {src_path}")

    base, ext = os.path.splitext(src_path)
    ext = ext.lower()

    if dst_path is None:
        dst_path = base + '.csv'

    dst_dir = os.path.dirname(os.path.abspath(dst_path))
    if dst_dir and not os.path.exists(dst_dir):
        os.makedirs(dst_dir, exist_ok=True)

    # Helper to stringify values (handle datetimes nicely)
    def _stringify(val):
        if val is None:
            return ""
        if isinstance(val, (datetime.datetime, datetime.date, datetime.time)):
            return val.isoformat()
        return str(val)

    # .xlsx and .xlsm -> openpyxl
    if ext in ('.xlsx', '.xlsm', '.xltx', '.xltm'):
        try:
            from openpyxl import load_workbook
        except Exception as e:
            raise ImportError("openpyxl is required to read .xlsx/.xlsm files. Install with `pip install openpyxl`.") from e

        wb = load_workbook(filename=src_path, read_only=True, data_only=True)
        sheets = wb.worksheets
        if sheet_index < 0 or sheet_index >= len(sheets):
            wb.close()
            raise IndexError(f"sheet_index {sheet_index} out of range (0..{len(sheets)-1})")
        ws = sheets[sheet_index]

        with open(dst_path, 'w', newline='', encoding=encoding) as f:
            writer = csv.writer(f, delimiter=delimiter, quoting=csv.QUOTE_MINIMAL)
            for row in ws.iter_rows(values_only=True):
                writer.writerow([_stringify(cell) for cell in row])
        wb.close()
        return dst_path

    # .xls -> xlrd
    elif ext == '.xls':
        try:
            import xlrd
        except Exception as e:
            raise ImportError("xlrd is required to read .xls files. Install with `pip install xlrd`.") from e

        wb = xlrd.open_workbook(src_path)
        if sheet_index < 0 or sheet_index >= wb.nsheets:
            raise IndexError(f"sheet_index {sheet_index} out of range (0..{wb.nsheets-1})")
        sh = wb.sheet_by_index(sheet_index)

        with open(dst_path, 'w', newline='', encoding=encoding) as f:
            writer = csv.writer(f, delimiter=delimiter, quoting=csv.QUOTE_MINIMAL)
            for r in range(sh.nrows):
                row = sh.row(r)
                out_row = []
                for cell in row:
                    ctype = cell.ctype
                    cval = cell.value
                    if ctype == xlrd.XL_CELL_EMPTY or ctype == xlrd.XL_CELL_BLANK:
                        out_row.append("")
                    elif ctype == xlrd.XL_CELL_DATE:
                        try:
                            dt = xlrd.xldate_as_datetime(cval, wb.datemode)
                            out_row.append(dt.isoformat())
                        except Exception:
                            out_row.append(str(cval))
                    else:
                        out_row.append(str(cval))
                writer.writerow(out_row)
        return dst_path

    else:
        raise ValueError(f"Unsupported file extension: {ext}. Supported: .xlsx, .xlsm, .xls")

# Example usage:
