import random
import string

def replace_random_substring(strings):
    def generate_random_string(length):
        return ''.join(random.choices(string.ascii_lowercase, k=length))

    def replace_substring(s):
        if not s:
            return s

        # Find all substrings between commas or at the beginning/end of the string
        substrings = []
        start = 0
        while start < len(s):
            if s[start] == ',':
                end = s.find(',', start + 1)
                if end == -1:
                    end = len(s)
                substrings.append(s[start:end])
                start = end + 1
            else:
                end = s.find(',', start)
                if end == -1:
                    end = len(s)
                substrings.append(s[start:end])
                start = end + 1

        if not substrings:
            return s

        # Choose a random substring to replace
        random_substring = random.choice(substrings)
        random_string = generate_random_string(len(random_substring))

        # Replace the chosen substring with the random string
        s = s.replace(random_substring, random_string)

        return s

    return [replace_substring(s) for s in strings]

# Example usage:
