```python
import json

def xml_to_json_file(xml_string: str, json_path: str, pretty: bool = True) -> dict:
    """
    Convert an XML string to a Python dictionary and save it as JSON.

    Tries to use the lightweight `xmltodict` library if available; if not,
    falls back to a small ElementTree-based converter included here.

    Parameters:
      xml_string (str): XML content as a string.
      json_path (str): Path to write the JSON file.
      pretty (bool): If True, writes JSON with indentation for readability.

    Returns:
      dict: The dictionary representation of the XML.

    Raises:
      ValueError: If the XML cannot be parsed.
      OSError: If writing the JSON file fails.
    """
    # Try to use xmltodict if installed (lightweight and convenient)
    try:
        import xmltodict  # type: ignore
        try:
            parsed = xmltodict.parse(xml_string)
        except Exception as e:
            raise ValueError(f"Failed to parse XML with xmltodict: {e}") from e
    except Exception:
        # Fallback: use xml.etree.ElementTree and convert to dict
        try:
            import xml.etree.ElementTree as ET
        except Exception as e:
            raise RuntimeError("No XML parser available") from e

        def _etree_to_dict(elem):
            """
            Convert an ElementTree element into a dict similar to xmltodict's output:
            - attributes become entries prefixed with '@'
            - text content becomes '#text' when element has children/attributes
            - repeated child tags become lists
            """
            node = {}
            # attributes
            for k, v in elem.attrib.items():
                node[f"@{k}"] = v

            # children
            children = list(elem)
            if children:
                child_dict = {}
                for child in children:
                    child_res = _etree_to_dict(child)
                    # child_res is {tag: value}
                    for tag, val in child_res.items():
                        if tag in child_dict:
                            # existing tag: promote to list if necessary
                            if isinstance(child_dict[tag], list):
                                child_dict[tag].append(val)
                            else:
                                child_dict[tag] = [child_dict[tag], val]
                        else:
                            child_dict[tag] = val
                node.update(child_dict)

            # text
            text = (elem.text or "").strip()
            if text:
                if node:
                    node["#text"] = text
                else:
                    # If no attrs/children, represent element as its text value
                    return {elem.tag: text}

            return {elem.tag: node}

        try:
            root = ET.fromstring(xml_string)
        except Exception as e:
            raise ValueError(f"Failed to parse XML with ElementTree: {e}") from e

        parsed = _etree_to_dict(root)

    # Write JSON to file
    try:
        with open(json_path, "w", encoding="utf-8") as f:
            if pretty:
                json.dump(parsed, f, ensure_ascii=False, indent=2)
            else:
                json.dump(parsed, f, ensure_ascii=False, separators=(",", ":"))
    except OSError as e:
        raise OSError(f"Failed to write JSON file '{json_path}': {e}") from e

    return parsed
```

Notes:
- If you want to use xmltodict for more feature-complete parsing, install it with: pip install xmltodict
- The fallback converter aims to give a reasonable dictionary representation (attributes as '@name', text as '#text') similar to xmltodict.

def json_to_excel(json_str: str, filename: str) -> None:
    """
    Convert a JSON string to an Excel (.xlsx) file and save it as `filename`.

    Behavior:
    - If JSON is an array of objects (list of dicts): writes a header row (keys collected
      in first-seen order) and one row per object. Missing keys produce empty cells.
    - If JSON is an array of arrays (list of lists/tuples): each inner list becomes a row.
    - If JSON is an array of scalars: each scalar becomes a single-cell row.
    - If JSON is an empty array: creates an .xlsx file with a single empty worksheet (no data rows).
    - If JSON is a single dict: writes header row and a single data row.
    - For nested lists/dicts inside cells, the nested object is stored as a JSON string.

    Requires: openpyxl (install with `pip install openpyxl`)
    """
    import json
    try:
        from openpyxl import Workbook
    except ImportError as e:
        raise ImportError("openpyxl is required. Install with 'pip install openpyxl'") from e

    data = json.loads(json_str)
    wb = Workbook()
    ws = wb.active

    # Helper to serialize complex cell values
    def serialize_cell(v):
        if isinstance(v, (dict, list)):
            return json.dumps(v, ensure_ascii=False)
        return v

    if isinstance(data, list):
        if len(data) == 0:
            # Create an XLSX with an empty sheet (no data rows)
            wb.save(filename)
            return

        # All dicts?
        if all(isinstance(item, dict) for item in data):
            # collect headers preserving first-seen order
            headers = []
            for item in data:
                for k in item.keys():
                    if k not in headers:
                        headers.append(k)
            ws.append(headers)
            for item in data:
                row = [serialize_cell(item.get(h, None)) for h in headers]
                ws.append(row)

        # All lists/tuples?
        elif all(isinstance(item, (list, tuple)) for item in data):
            for item in data:
                ws.append([serialize_cell(v) for v in item])

        # All scalars?
        elif all(not isinstance(item, (dict, list, tuple)) for item in data):
            for item in data:
                ws.append([serialize_cell(item)])

        # Mixed or other complex structures: write each item as a JSON string in one column
        else:
            for item in data:
                ws.append([serialize_cell(item)])

    elif isinstance(data, dict):
        headers = list(data.keys())
        ws.append(headers)
        ws.append([serialize_cell(data[h]) for h in headers])

    else:
        # Scalar root JSON -> single cell
        ws.append([serialize_cell(data)])

    wb.save(filename)

