def analyze_sales_data(data, column, *, xlabel=None, title=None):
    """
    Analyze sales data and return statistics and a bar chart figure for the given column.

    Parameters:
    - data: list of records:
        - list of dicts -> column should be a key (str)
        - list of lists/tuples -> column should be an index (int)
        - list of numbers -> column can be None (or 0) and values are taken directly
    - column: key (str) or index (int) identifying the column to analyze
    - xlabel: optional label for x axis (defaults to 'Index' or provided column)
    - title: optional title for the plot (defaults to 'Bar chart of {column}')

    Returns:
    - (stats, fig) where stats is a dict: {'sum': ..., 'mean': ..., 'min': ..., 'max': ..., 'count': ...}
      and fig is a matplotlib.figure.Figure (the bar chart). The figure is not shown.

    Raises:
    - ValueError if no numeric values found for the specified column or if inputs are invalid.
    """
    # Lightweight imports
    import math
    import matplotlib
    # Use a non-interactive backend so no display is required
    try:
        matplotlib.use('Agg', force=True)
    except Exception:
        # If backend was already set to something else, ignore
        pass
    import matplotlib.pyplot as plt

    # Helper to coerce to float if possible, otherwise return None
    def _to_number(x):
        if x is None:
            return None
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            if math.isfinite(x):
                return float(x)
            return None
        if isinstance(x, str):
            s = x.strip().replace(',', '')  # allow "1,234.56"
            if s == '':
                return None
            try:
                val = float(s)
                if math.isfinite(val):
                    return val
            except Exception:
                return None
        return None

    # Normalize data type and extract values
    if not isinstance(data, list):
        raise ValueError("data must be a list (of dicts, sequences, or numbers).")

    values = []
    missing = 0
    # Determine mode: list of dicts, list of sequences, or list of scalars
    is_all_dicts = all(isinstance(rec, dict) for rec in data if rec is not None)
    is_all_seqs = all(isinstance(rec, (list, tuple)) for rec in data if rec is not None)
    is_all_scalars = all(not isinstance(rec, (list, tuple, dict)) for rec in data)

    if is_all_dicts and column is None:
        raise ValueError("For list of dicts you must provide a column key (string).")
    if is_all_seqs and (not isinstance(column, int)):
        raise ValueError("For list of lists/tuples you must provide a column index (int).")

    if is_all_scalars:
        # Treat data itself as values
        for rec in data:
            num = _to_number(rec)
            if num is None:
                missing += 1
            else:
                values.append(num)
    elif is_all_dicts:
        key = column
        for rec in data:
            # skip records that are not dicts (None or other) defensively
            if not isinstance(rec, dict):
                missing += 1
                continue
            val = rec.get(key, None)
            num = _to_number(val)
            if num is None:
                missing += 1
            else:
                values.append(num)
    elif is_all_seqs:
        idx = column
        for rec in data:
            if not isinstance(rec, (list, tuple)):
                missing += 1
                continue
            try:
                val = rec[idx]
            except Exception:
                missing += 1
                continue
            num = _to_number(val)
            if num is None:
                missing += 1
            else:
                values.append(num)
    else:
        # Mixed types: try best-effort extraction based on column type
        if isinstance(column, str):
            for rec in data:
                if isinstance(rec, dict):
                    val = rec.get(column, None)
                elif isinstance(rec, (list, tuple)):
                    # try treat column as key? skip
                    val = None
                else:
                    val = None
                num = _to_number(val)
                if num is None:
                    missing += 1
                else:
                    values.append(num)
        elif isinstance(column, int):
            for rec in data:
                if isinstance(rec, (list, tuple)):
                    try:
                        val = rec[column]
                    except Exception:
                        val = None
                elif isinstance(rec, dict):
                    # try interpret integer key in dict
                    val = rec.get(column, None)
                else:
                    val = None
                num = _to_number(val)
                if num is None:
                    missing += 1
                else:
                    values.append(num)
        else:
            raise ValueError("Cannot infer data structure. Provide column as str (for dicts) or int (for sequences).")

    if len(values) == 0:
        raise ValueError("No numeric values found for the specified column.")

    total = sum(values)
    count = len(values)
    mean = total / count
    minimum = min(values)
    maximum = max(values)

    stats = {
        'sum': total,
        'mean': mean,
        'min': minimum,
        'max': maximum,
        'count': count,
        'missing': missing
    }

    # Build bar chart (values vs index)
    fig, ax = plt.subplots(figsize=(8, 4.5))
    x = list(range(len(values)))
    ax.bar(x, values, color='tab:blue', alpha=0.8)
    ax.set_xlabel(xlabel if xlabel is not None else ('Index' if xlabel is None else xlabel))
    ax.set_ylabel(str(column) if column is not None else 'Value')
    ax.set_title(title if title is not None else f'Bar chart of {column}')
    ax.grid(axis='y', linestyle='--', alpha=0.3)

    # Tight layout but do not show
    fig.tight_layout()

    # Return stats and the Figure. The caller can save or display the figure as desired,
    # e.g., fig.savefig('out.png') or display in Jupyter with display(fig).
    return stats, fig
