def export_functions_to_csv(f_list, file_path):
    """
    Exports specifications of functions in `f_list` to a CSV file at `file_path`.
    CSV columns:
      - 'Function Name'
      - 'Number of Arguments'  (counts all parameters, including *args/**kwargs)
      - 'Defaults'            (formatted as "arg=repr(default), ...")
      - 'Annotations'         (formatted as "arg: annotation, ..., return: annotation")
      - 'Is Lambda'           (True/False)
    Uses only Python standard lightweight libraries (inspect, csv).
    """
    import csv
    import inspect

    def format_annotation(a):
        if a is inspect._empty:
            return None
        # Try to display types/readable names nicely
        try:
            # Most types/classes have a __name__
            if hasattr(a, "__name__"):
                return a.__name__
            # typing types and others fallback to str()
            return str(a)
        except Exception:
            return repr(a)

    def format_defaults(params):
        parts = []
        for name, p in params.items():
            if p.default is not inspect._empty:
                parts.append(f"{name}={repr(p.default)}")
        return ", ".join(parts)

    def format_annotations(params, return_ann):
        parts = []
        for name, p in params.items():
            ann = format_annotation(p.annotation)
            if ann is not None:
                parts.append(f"{name}: {ann}")
        ret = format_annotation(return_ann)
        if ret is not None:
            parts.append(f"return: {ret}")
        return ", ".join(parts)

    # Write CSV
    with open(file_path, mode="w", newline="", encoding="utf-8") as csvfile:
        writer = csv.DictWriter(
            csvfile,
            fieldnames=[
                "Function Name",
                "Number of Arguments",
                "Defaults",
                "Annotations",
                "Is Lambda",
            ],
        )
        writer.writeheader()

        for f in f_list:
            # Ensure it's callable; skip otherwise
            if not callable(f):
                continue

            try:
                sig = inspect.signature(f)
            except (ValueError, TypeError):
                # Some builtins or objects may not provide a signature
                params = {}
                num_args = 0
                defaults = ""
                annotations = ""
            else:
                params = sig.parameters
                num_args = len(params)
                defaults = format_defaults(params)
                annotations = format_annotations(params, sig.return_annotation)

            name = getattr(f, "__name__", repr(f))
            is_lambda = getattr(f, "__name__", "") == "<lambda>"

            writer.writerow(
                {
                    "Function Name": name,
                    "Number of Arguments": num_args,
                    "Defaults": defaults,
                    "Annotations": annotations,
                    "Is Lambda": str(bool(is_lambda)),
                }
            )

def export_function_specs_to_csv(f_list, file_path):
    """
    Export specifications of functions in `f_list` to a CSV file at `file_path`.

    CSV columns:
    - 'Function Name': The name of the function.
    - 'Number of Arguments': The number of arguments the function takes (count of signature parameters).
    - 'Defaults': Default values for the function's arguments, if any (formatted as "arg=repr(default)").
    - 'Annotations': Type annotations of the function's arguments and return value, if any
                   (formatted as "arg:Annotation, return:Annotation").
    - 'Is Lambda': Boolean indicating whether the function is a lambda function.

    Notes:
    - Uses only Python standard library (inspect, csv).
    - If a callable does not expose a signature (e.g. some builtins), the corresponding
      fields will be left empty where the information could not be obtained.
    """
    import inspect
    import csv

    def _annotation_to_str(a):
        # Represent annotation in a readable way
        if a is inspect._empty:
            return ''
        # Common case: a class or builtin type
        if isinstance(a, type):
            return a.__name__
        # Typing generics (typing.List[int], etc.) often have __repr__ okay
        try:
            # Remove the "typing." prefix for readability when present
            s = repr(a)
            if s.startswith('typing.'):
                s = s.split('typing.', 1)[1]
            return s
        except Exception:
            try:
                return str(a)
            except Exception:
                return repr(a)

    def _default_to_str(d):
        if d is inspect._empty:
            return ''
        try:
            return repr(d)
        except Exception:
            return str(d)

    headers = ['Function Name', 'Number of Arguments', 'Defaults', 'Annotations', 'Is Lambda']
    rows = []

    for f in f_list:
        row = {
            'Function Name': getattr(f, '__name__', type(f).__name__),
            'Number of Arguments': '',
            'Defaults': '',
            'Annotations': '',
            'Is Lambda': getattr(f, '__name__', '') == '<lambda>'
        }

        if not callable(f):
            # Non-callables: leave most fields blank but record name
            rows.append([row[h] for h in headers])
            continue

        try:
            sig = inspect.signature(f)
            params = sig.parameters
            row['Number of Arguments'] = str(len(params))

            # Collect defaults
            defaults_parts = []
            for pname, p in params.items():
                if p.default is not inspect._empty:
                    defaults_parts.append(f"{pname}={_default_to_str(p.default)}")
            row['Defaults'] = ', '.join(defaults_parts)

            # Collect annotations (including return)
            ann_parts = []
            for pname, p in params.items():
                if p.annotation is not inspect._empty:
                    ann_parts.append(f"{pname}:{_annotation_to_str(p.annotation)}")
            if sig.return_annotation is not inspect._empty:
                ann_parts.append(f"return:{_annotation_to_str(sig.return_annotation)}")
            row['Annotations'] = ', '.join(ann_parts)

        except (ValueError, TypeError):
            # Some callables (builtins, extension types) may not expose a signature
            # Leave the fields blank if we can't obtain them
            pass

        rows.append([row[h] for h in headers])

    # Write to CSV
    with open(file_path, mode='w', newline='', encoding='utf-8') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(headers)
        writer.writerows(rows)

