        defaults_repr = ""
        annotations_repr = ""
        num_args = "N/A"

        # Try to get a signature; if not possible, try __call__, else leave N/A
        sig = None
        try:
            sig = inspect.signature(f)
        except (ValueError, TypeError):
            # Try callable objects' __call__
            call_attr = getattr(f, "__call__", None)
            if call_attr and call_attr is not f:
                try:
                    sig = inspect.signature(call_attr)
                except (ValueError, TypeError):
                    sig = None

        if sig is not None:
            params = list(sig.parameters.values())
            # Count parameters excluding *args and **kwargs
            num_args = sum(
                1
                for p in params
                if p.kind not in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD)
            )

            # Defaults: collect params that have defaults
            defaults = {}
            for p in params:
                if p.default is not inspect._empty:
                    try:
                        defaults[p.name] = repr(p.default)
                    except Exception:
                        defaults[p.name] = "<unrepr-able default>"
            defaults_repr = str(defaults) if defaults else ""

            # Annotations: collect param annotations and return annotation if present
            ann = {}
            for p in params:
                if p.annotation is not inspect._empty:
                    try:
                        ann[p.name] = repr(p.annotation)
                    except Exception:
                        ann[p.name] = "<unrepr-able annotation>"
            if sig.return_annotation is not inspect._empty:
                try:
                    ann["return"] = repr(sig.return_annotation)
                except Exception:
                    ann["return"] = "<unrepr-able annotation>"
            annotations_repr = str(ann) if ann else ""

        # Append row
        rows.append(
            {
                "Function Name": func_name,
                "Number of Arguments": num_args,
                "Defaults": defaults_repr,
                "Annotations": annotations_repr,
                "Is Lambda": bool(is_lambda),
            }
        )

    # Write CSV
    with open(file_path, "w", newline="", encoding="utf-8") as csvfile:
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)

import urllib.request
import urllib.error
import json
import unicodedata

def get_github_user_ascii(username, timeout=10):
    """
    Retrieve GitHub user info for `username`, normalize all string data to ASCII, and return a dict.
    Uses only Python standard library (urllib) and unicodedata for normalization.

    Parameters:
    - username (str): GitHub username (required).
    - timeout (float): optional request timeout in seconds (default 10).

    Returns:
    - dict: the JSON response from GitHub with all string keys and values normalized to ASCII.

    Raises:
    - ValueError: if username is empty or user not found (HTTP 404).
    - RuntimeError: for other HTTP errors (403 rate limit, etc.) or parsing errors.
    - URLError: for network-level issues (propagated from urllib).
    """
    if not isinstance(username, str) or not username.strip():
        raise ValueError("username must be a non-empty string")

    url = f"https://api.github.com/users/{urllib.parse.quote(username)}"
    req = urllib.request.Request(url, headers={"User-Agent": "python-urllib", "Accept": "application/vnd.github.v3+json"})

    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode("utf-8")
    except urllib.error.HTTPError as e:
        # Try to parse JSON error message if present
        msg = ""
        try:
            body = e.read().decode("utf-8")
            parsed = json.loads(body)
            if isinstance(parsed, dict) and "message" in parsed:
                msg = f": {parsed['message']}"
        except Exception:
            pass
        if e.code == 404:
            raise ValueError(f'GitHub user "{username}" not found{msg}')
        elif e.code == 403:
            raise RuntimeError(f"GitHub API error 403 (forbidden/rate-limited){msg}")
        else:
            raise RuntimeError(f"GitHub API HTTP error {e.code}{msg}") from e

    try:
        data = json.loads(raw)
    except Exception as e:
        raise RuntimeError("Failed to parse GitHub response as JSON") from e

    def normalize(obj):
        # Normalize strings to ASCII, recursively handle dicts and lists
        if isinstance(obj, str):
            nf = unicodedata.normalize("NFKD", obj)
            return nf.encode("ascii", "ignore").decode("ascii")
        elif isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                # normalize string keys too (unlikely non-ASCII, but safe)
                new_key = normalize(k) if isinstance(k, str) else k
                # if collision happens due to normalization, later keys overwrite earlier ones
                new[new_key] = normalize(v)
            return new
        elif isinstance(obj, list):
            return [normalize(item) for item in obj]
        else:
            return obj

    return normalize(data)

# Example:
# user = get_github_user_ascii("torvalds")
# print(user["name"], user["location"])

