```python
import json
import unicodedata

# Try to use requests (lightweight). If not available, fall back to urllib.
try:
    import requests
    _HAS_REQUESTS = True
except Exception:
    import urllib.request
    _HAS_REQUESTS = False


def get_github_user_normalized(username, token=None, timeout=10):
    """
    Retrieve GitHub user info for `username`, normalize all string data to ASCII,
    and return a dictionary of normalized data.

    Parameters:
    - username (str): GitHub username to look up.
    - token (str, optional): Personal access token to increase rate limit (passed in Authorization header).
    - timeout (int or float, optional): Request timeout in seconds.

    Returns:
    - dict: Normalized user data (keys and string values converted to ASCII).

    Raises:
    - ValueError: if username is empty or user is not found.
    - RuntimeError: for other HTTP/network errors.
    """
    if not username or not isinstance(username, str):
        raise ValueError("username must be a non-empty string")

    url = f"https://api.github.com/users/{username}"
    headers = {"Accept": "application/vnd.github.v3+json"}
    if token:
        headers["Authorization"] = f"token {token}"

    # Fetch data
    if _HAS_REQUESTS:
        resp = requests.get(url, headers=headers, timeout=timeout)
        if resp.status_code == 404:
            raise ValueError(f"GitHub user '{username}' not found (404).")
        if resp.status_code >= 400:
            raise RuntimeError(f"GitHub API error {resp.status_code}: {resp.text}")
        data = resp.json()
    else:
        req = urllib.request.Request(url, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                body = resp.read()
                data = json.loads(body.decode("utf-8"))
        except urllib.error.HTTPError as e:
            if e.code == 404:
                raise ValueError(f"GitHub user '{username}' not found (404).")
            body = e.read().decode("utf-8", errors="ignore")
            raise RuntimeError(f"GitHub API error {e.code}: {body}")

    # Normalization helpers
    def _to_ascii(s):
        # NFKD to decompose accents, then drop non-ascii bytes
        if not isinstance(s, str):
            return s
        nkfd = unicodedata.normalize("NFKD", s)
        return nkfd.encode("ascii", "ignore").decode("ascii")

    def _normalize(obj):
        # Recursively normalize dicts, lists/tuples, and strings
        if isinstance(obj, str):
            return _to_ascii(obj)
        if isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                new_key = _to_ascii(k) if isinstance(k, str) else k
                new[new_key] = _normalize(v)
            return new
        if isinstance(obj, list):
            return [_normalize(i) for i in obj]
        if isinstance(obj, tuple):
            return tuple(_normalize(i) for i in obj)
        # Leave numbers, booleans, None as-is
        return obj

    normalized = _normalize(data)
    # Ensure we return a dict (GitHub /users/:username returns an object)
    if not isinstance(normalized, dict):
        raise RuntimeError("Unexpected response format from GitHub API")
    return normalized

# Example usage:
# user = get_github_user_normalized("torvalds")
# print(user["name"], user["bio"])
