def word_length_counts_by_start(data, letter, case_sensitive=False, use_pandas=True):
    """
    Convert a dict-of-lists to a DataFrame, filter rows where the 'Word' column
    begins with the specified letter, compute lengths of the filtered words, and
    return a dict mapping word length -> count.

    Parameters:
    - data: dict of lists, must contain key 'Word'
    - letter: single-character string to match at the start of each word
    - case_sensitive: bool, whether the match should be case-sensitive (default False)
    - use_pandas: bool, try to use pandas for the DataFrame conversion; if pandas
                  is not available it will fall back to a pure-Python implementation

    Returns:
    - dict: {word_length: count}
    """
    if 'Word' not in data:
        raise ValueError("Input dict must contain a 'Word' column/key.")

    if not isinstance(letter, str) or len(letter) == 0:
        raise ValueError("`letter` must be a non-empty string.")

    # Try using pandas if requested
    if use_pandas:
        try:
            import pandas as pd
            df = pd.DataFrame(data)
            # ensure no NaN issues and treat values as strings
            words = df['Word'].fillna('').astype(str)
            if case_sensitive:
                mask = words.str.startswith(letter)
            else:
                mask = words.str.lower().str.startswith(letter.lower())
            filtered = words[mask]
            if filtered.empty:
                return {}
            lengths = filtered.str.len()
            counts = lengths.value_counts().sort_index().to_dict()
            # convert numpy ints to native ints
            return {int(k): int(v) for k, v in counts.items()}
        except Exception:
            # fall back to pure-Python below if pandas import/usage fails
            pass

    # Pure-Python fallback (no external libraries)
    from collections import Counter
    words = data.get('Word', [])
    if not isinstance(words, (list, tuple)):
        # try to coerce single column to list
        words = list(words)

    if case_sensitive:
        starts_with = lambda w: str(w).startswith(letter)
    else:
        low_letter = letter.lower()
        starts_with = lambda w: str(w).lower().startswith(low_letter)

    filtered_lengths = (len(str(w)) for w in words if w is not None and starts_with(w))
    counter = Counter(filtered_lengths)
    # convert Counter to regular dict with int keys/values
    return {int(k): int(v) for k, v in sorted(counter.items())}


