Here's a self-contained Python function that converts a dict-of-lists to a DataFrame (if pandas is available), filters rows where the 'Word' column begins with a given letter, computes word lengths for the filtered rows, and returns a dictionary mapping each length to its count. If pandas is not installed, it falls back to a pure-Python (no-external-library) implementation.

def filter_word_lengths(data, letter, case_sensitive=False):
    """
    Filter rows in a dict-of-lists where the 'Word' column begins with `letter`,
    then compute the lengths of the filtered words and return a dict mapping
    length -> count.

    Parameters:
    - data: dict of lists, must include key 'Word' (e.g. {'Word': ['apple', 'banana'], 'Other': [...]})
    - letter: single-character string (or longer substring) used for "startswith" filtering
    - case_sensitive: if False (default), matching is case-insensitive

    Returns:
    - dict: {word_length: count, ...}

    Notes:
    - Uses pandas if available for convenience; otherwise uses a pure-Python fallback.
    - If no words match, returns an empty dict.
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dict of lists")
    if 'Word' not in data:
        raise KeyError("data must contain a 'Word' key")
    if not isinstance(letter, str) or letter == "":
        raise ValueError("letter must be a non-empty string")

    # Try to use pandas if available
    try:
        import pandas as pd
        df = pd.DataFrame(data)
        if 'Word' not in df.columns:
            raise KeyError("Converted DataFrame does not contain 'Word' column")

        words = df['Word'].astype(str)

        if case_sensitive:
            mask = words.str.startswith(letter, na=False)
        else:
            mask = words.str.lower().str.startswith(letter.lower(), na=False)

        filtered = words[mask]
        if filtered.empty:
            return {}

        lengths = filtered.str.len()
        counts = lengths.value_counts().sort_index().to_dict()
        # Convert numpy types to native Python ints
        return {int(k): int(v) for k, v in counts.items()}

    except ImportError:
        # Pure-Python fallback (no external libs)
        raw_words = data.get('Word')
        if raw_words is None:
            raise KeyError("data must contain a 'Word' key")

        if case_sensitive:
            predicate = lambda w: isinstance(w, str) and w.startswith(letter)
        else:
            lower_letter = letter.lower()
            predicate = lambda w: isinstance(w, str) and w.lower().startswith(lower_letter)

        counts = {}
        for w in raw_words:
            if predicate(w):
                l = len(w)
                counts[l] = counts.get(l, 0) + 1
        return counts

