Here is a self-contained Python function that stems every word in a sentence except the last one and returns the frequency of each resulting stem. It uses only Python's standard library (lightweight) and a small rule-based stemmer (no external dependencies).

```python
import re
from collections import Counter

def stem_frequency(sentence):
    """
    Stem every word in `sentence` except the last word, then count frequency of each stem.
    - Tokenizes on word characters (keeps apostrophes inside words).
    - Lowercases tokens.
    - Uses a small heuristic stemmer (not a full Porter implementation).
    - The final word is left unchanged (but lowercased) and included in the counts.

    Args:
        sentence (str): input sentence.

    Returns:
        dict: mapping stem -> count

    Example:
        >>> stem_frequency("Running runners ran easily")
        {'run': 2, 'ran': 1, 'easily': 1}
    """
    def simple_stem(word):
        # Very small heuristic stemmer:
        if len(word) <= 3:
            return word
        if word.endswith("ies") and len(word) > 3:
            return word[:-3] + "y"
        if word.endswith("ing") and len(word) > 4:
            stem = word[:-3]
            # reduce double consonant (running -> run)
            if len(stem) >= 2 and stem[-1] == stem[-2]:
                stem = stem[:-1]
            return stem
        if word.endswith("ed") and len(word) > 3:
            stem = word[:-2]
            if len(stem) >= 2 and stem[-1] == stem[-2]:
                stem = stem[:-1]
            return stem
        # common endings to strip if remaining stem is reasonably long
        for suf in ("ization", "ational", "fulness", "iveness", "tional", "lessness"):
            if word.endswith(suf) and len(word) - len(suf) >= 3:
                return word[:-len(suf)]
        if word.endswith("es") and not word.endswith("ses") and len(word) > 3:
            return word[:-2]
        if word.endswith("s") and not word.endswith("ss") and len(word) > 3:
            return word[:-1]
        for suf in ("ly", "ment", "ness", "tion", "er", "or", "al", "ive", "ous"):
            if word.endswith(suf) and len(word) - len(suf) >= 3:
                return word[:-len(suf)]
        return word

    # Tokenize: keep letters, digits, underscores and internal apostrophes
    tokens = re.findall(r"\b[\w']+\b", sentence.lower())
    if not tokens:
        return {}

    stems = []
    last_index = len(tokens) - 1
    for i, tok in enumerate(tokens):
        if i == last_index:
            stems.append(tok)  # do not stem the last word
        else:
            stems.append(simple_stem(tok))

    return dict(Counter(stems))


# Quick demo
