Here is a self-contained Python function that stems every word in a sentence except the last and returns a frequency dictionary of the stems. It uses only the built-in re module and a small, lightweight rule-based stemmer (not a full Porter implementation, but fast and compact).

```python
import re
from typing import Dict

def stem_freq(sentence: str) -> Dict[str, int]:
    """
    Stem every word in `sentence` except the last word, and count stem frequencies.
    Uses a small rule-based stemmer (lightweight, no external libraries).

    Args:
        sentence: input string.

    Returns:
        dict mapping stem -> count (only for all words except the last).
    """
    def simple_stem(word: str) -> str:
        # very small heuristic stemmer: common suffix stripping
        if len(word) <= 3:
            return word
        # handle plural forms
        if word.endswith("sses"):
            return word[:-2]            # dresses -> dress
        if word.endswith("ies"):
            return word[:-3] + "i"      # flies -> fli (keeps short form)
        if word.endswith("ss"):
            return word                # 'ss' stays
        if word.endswith("s"):
            # avoid chopping short words like "is"
            if len(word) > 3:
                word = word[:-1]
        # handle 'ing' and 'ed'
        for suf in ("ing", "ed"):
            if word.endswith(suf) and len(word) - len(suf) > 2:
                word = word[:-len(suf)]
                # if resulting word ends with a double consonant, reduce it (e.g., 'running' -> 'run')
                if len(word) >= 2 and word[-1] == word[-2]:
                    word = word[:-1]
                break
        # handle 'ly'
        if word.endswith("ly") and len(word) > 4:
            word = word[:-2]
        return word

    # Tokenize on word boundaries, lowercase. This keeps only letters/digits/underscore as word chars.
    tokens = re.findall(r"\b\w+\b", sentence.lower())
    if not tokens:
        return {}

    counts: Dict[str, int] = {}
    # process all tokens except the last
    for tok in tokens[:-1]:
        stem = simple_stem(tok)
        counts[stem] = counts.get(stem, 0) + 1

    return counts

