Here's a self-contained Python function that flattens a nested list (of arbitrary depth) and returns the median of all numeric elements. It uses the lightweight standard-library module statistics.

```python
from statistics import median
from typing import Any

def median_nested(L: Any):
    """
    Compute the median of all elements in a nested list/tuple/set structure.

    - Accepts nested lists/tuples/sets of arbitrary depth.
    - Ignores string/bytes as containers (they are treated as scalar values).
    - Raises ValueError if no elements are found.
    - Raises TypeError if non-numeric scalars are encountered (unless they can be converted to float).

    Example:
        median_nested([1, [2, 3], [[4], 5]])  -> 3
        median_nested([[1, 2], [3, 4]])      -> 2.5
    """
    def _flatten(obj):
        # Treat only list/tuple/set as containers to recurse into.
        if isinstance(obj, (list, tuple, set)):
            for elt in obj:
                yield from _flatten(elt)
        else:
            yield obj

    values = list(_flatten(L))
    if not values:
        raise ValueError("No elements found in the input structure")

    # Try computing median directly; if some items are non-numeric try to coerce to float.
    try:
        return median(values)
    except TypeError:
        coerced = []
        for v in values:
            if isinstance(v, (int, float)):
                coerced.append(v)
            else:
                try:
                    coerced.append(float(v))
                except Exception:
                    raise TypeError(f"Non-numeric element encountered and cannot be converted to float: {v!r}")
        return median(coerced)
