Here's a single self-contained Python function that flattens a nested list of arbitrary depth, extracts numeric values, and returns the interquartile range (IQR). It uses only the standard library (no heavy external packages). If available, it uses statistics.quantiles; otherwise it falls back to a small linear-interpolation percentile implementation.

```python
def iqr(L):
    """
    Calculate the interquartile range (IQR) of all numeric elements in a nested list/tuple L.
    Works with arbitrary nesting depth. Non-numeric elements are ignored.
    Uses statistics.quantiles if available, otherwise a simple linear-interpolation percentile.

    Returns:
        float: Q3 - Q1

    Raises:
        ValueError: if no numeric data is found.
    """
    import numbers

    # flatten nested lists/tuples (but don't treat strings as sequences)
    def _flatten(x):
        for item in x:
            if isinstance(item, (list, tuple)):
                yield from _flatten(item)
            else:
                yield item

    data = [v for v in _flatten(L) if isinstance(v, numbers.Real) and not isinstance(v, bool)]
    if not data:
        raise ValueError("no numeric data found in input")

    data.sort()

    # Try to use statistics.quantiles (lightweight, in stdlib). If unavailable, use a small fallback.
    try:
        from statistics import quantiles
        q1, _, q3 = quantiles(data, n=4, method='inclusive')
    except Exception:
        # linear-interpolation percentile (same idea as numpy.percentile with interpolation='linear')
        def _percentile(sorted_data, p):
            n = len(sorted_data)
            if n == 1:
                return float(sorted_data[0])
            pos = p / 100.0 * (n - 1)
            k = int(pos)
            d = pos - k
            if k + 1 < n:
                return sorted_data[k] + d * (sorted_data[k + 1] - sorted_data[k])
            else:
                return float(sorted_data[k])
        q1 = _percentile(data, 25)
        q3 = _percentile(data, 75)

    return float(q3 - q1)
```

Example:
- iqr([[1, 2, [3]], 4, 5]) -> 3.0 (Q1=1.5, Q3=4.5 => IQR=3.0)

Here's a small, self-contained Python function that uses only the lightweight standard csv and collections libraries. It returns a dict mapping each column name to the most common value (tie broken by alphabetical order). If the CSV is empty (no header or no data rows) it returns an empty dict.

```python
def most_common_per_column(csv_source):
    """
    Return the most common value for each column in a CSV (with header).

    - csv_source may be a file path (str/Path) or a file-like object open for reading.
    - Values are stripped of leading/trailing whitespace.
    - None or missing fields are treated as the empty string ''.
    - If multiple values tie for most common, the values are sorted alphabetically and the first is chosen.
    - If the CSV is empty (no header or no data rows), returns {}.
    """
    import csv
    from collections import Counter

    opened_here = False
    f = None
    try:
        # Accept either a path/string or a file-like object
        if hasattr(csv_source, "read"):
            f = csv_source
        else:
            f = open(csv_source, "r", encoding="utf-8-sig", newline="")
            opened_here = True

        reader = csv.DictReader(f)
        fieldnames = reader.fieldnames
        if not fieldnames:
            return {}

        counters = {fn: Counter() for fn in fieldnames}
        row_count = 0
        for row in reader:
            row_count += 1
            for fn in fieldnames:
                val = row.get(fn)
                if val is None:
                    val = ""
                else:
                    val = val.strip()
                counters[fn][val] += 1

        if row_count == 0:
            return {}

        result = {}
        for fn, cnt in counters.items():
            if not cnt:
                continue
            max_count = max(cnt.values())
            candidates = [v for v, c in cnt.items() if c == max_count]
            # Tie-breaker: alphabetical order (default string order)
            result[fn] = sorted(candidates)[0]

        return result

    finally:
        if opened_here and f is not None:
            f.close()
```

