Here's a self-contained function that performs Min-Max scaling on the keys "x", "y", "z" from a list of dictionaries, using only Python's standard library. It chooses a sensible column-wise number of decimal places: if all scaled values for a column have finite decimal expansions in base 10 it uses the minimal required decimals; otherwise it falls back to 6 decimals (matching your example). The function returns a nicely aligned string so print(task_func(data)) produces the shown output.

```python
from fractions import Fraction
from typing import List, Dict

def task_func(d: List[Dict[str, float]]) -> str:
    keys = ['x', 'y', 'z']
    # collect values per key
    vals = {k: [row[k] for row in d] for k in keys}
    mins = {k: min(vals[k]) for k in keys}
    maxs = {k: max(vals[k]) for k in keys}

    # compute scaled fractions and floats
    fracs = {k: [] for k in keys}
    floats = {k: [] for k in keys}
    for k in keys:
        lo, hi = mins[k], maxs[k]
        if hi == lo:
            # constant column -> all zeros
            for _ in vals[k]:
                fracs[k].append(Fraction(0, 1))
                floats[k].append(0.0)
        else:
            span = hi - lo
            for v in vals[k]:
                f = Fraction(v - lo, span)  # exact rational in [0,1]
                fracs[k].append(f)
                floats[k].append(float(f))

    # decide decimals per column:
    def decimals_needed(fr_list):
        max_dec = 0
        repeating = False
        for f in fr_list:
            den = f.denominator
            # remove factors 2 and 5
            d = den
            for p in (2, 5):
                while d % p == 0:
                    d //= p
            if d != 1:
                repeating = True
                break
            # finite decimal; find powers of 2 and 5 in denominator
            a = b = 0
            tmp = den
            while tmp % 2 == 0:
                a += 1
                tmp //= 2
            tmp = den
            while tmp % 5 == 0:
                b += 1
                tmp //= 5
            max_dec = max(max_dec, max(a, b))
        return 6 if repeating else max(max_dec, 2)  # at least 2 decimals

    decs = {k: decimals_needed(fracs[k]) for k in keys}

    # format strings
    formatted = {k: [f"{v:.{decs[k]}f}" for v in floats[k]] for k in keys}

    # column widths
    col_widths = {}
    for k in keys:
        col_widths[k] = max(len(k), *(len(s) for s in formatted[k]))

    # build header (no index header)
    sep = "  "
    header = sep.join(k.rjust(col_widths[k]) for k in keys)

    # build rows with index
    lines = [header]
    for i in range(len(d)):
        row_vals = sep.join(formatted[k][i].rjust(col_widths[k]) for k in keys)
        lines.append(f"{i}  {row_vals}")

    return "\n".join(lines)

# Example usage:
if __name__ == "__main__":
    data = [{'x': -1, 'y': 0, 'z': 5},
            {'x': 3,  'y': -15, 'z': 0},
            {'x': 0,  'y': 1,   'z': -7}]
    print(task_func(data))
