```python
from collections import Counter
from typing import List, Dict, Any

def count_xyz_values(d: List[Dict[str, Any]]) -> Dict[str, Dict[Any, int]]:
    """
    Count occurrences of values for keys 'x', 'y' and 'z' in list of dicts `d`.

    Returns a dict mapping each key ('x','y','z') to a dict of value -> count.
    Unhashable values (like lists) are converted to tuples; other unhashable
    objects are stringified as a fallback.
    """
    counters = {k: Counter() for k in ("x", "y", "z")}
    for item in d:
        if not isinstance(item, dict):
            continue
        for k in counters:
            if k in item:
                v = item[k]
                try:
                    counters[k][v] += 1
                except TypeError:
                    # handle unhashable values (lists, sets, etc.)
                    if isinstance(v, (list, set)):
                        hv = tuple(v)
                    else:
                        hv = str(v)
                    counters[k][hv] += 1

    # convert Counter objects to plain dicts for easier use/serialization
    return {k: dict(counters[k]) for k in counters}
```

