Here's a small, self-contained Python function using the standard library's collections.Counter. It counts occurrences of values for keys "x", "y", and "z" in an iterable of dictionaries. By default it returns an aggregated count across those keys; set per_key=True to get counts per key.

```python
from collections import Counter
from typing import Iterable, Dict, Any, Union

def count_xyz(d: Iterable[Dict[str, Any]], per_key: bool = False) -> Union[Dict[Any, int], Dict[str, Dict[Any, int]]]:
    """
    Count occurrences of values for keys 'x', 'y', 'z' in iterable of dicts `d`.

    Args:
      d: Iterable of dictionaries.
      per_key: If False (default) return a single dict of value->count aggregated over x,y,z.
               If True return a dict mapping each key ('x','y','z') to its own value->count dict.

    Returns:
      If per_key is False: dict(value -> count)
      If per_key is True: dict(key -> dict(value -> count))
    """
    keys = ('x', 'y', 'z')

    def _make_hashable(v):
        # Convert common unhashable containers to hashable forms (lists -> tuples).
        if isinstance(v, list):
            return tuple(v)
        return v

    if per_key:
        out = {k: Counter() for k in keys}
        for item in d:
            if not isinstance(item, dict):
                continue
            for k in keys:
                if k in item:
                    try:
                        val = _make_hashable(item[k])
                        out[k][val] += 1
                    except TypeError:
                        # skip unhashable values we can't convert
                        continue
        # convert Counters to plain dicts
        return {k: dict(out[k]) for k in keys}
    else:
        agg = Counter()
        for item in d:
            if not isinstance(item, dict):
                continue
            for k in keys:
                if k in item:
                    try:
                        val = _make_hashable(item[k])
                        agg[val] += 1
                    except TypeError:
                        continue
        return dict(agg)
```

