```python
import os
import re
import csv
import calendar
from datetime import datetime
import matplotlib.pyplot as plt
import matplotlib.dates as mdates

def plot_sales_from_csvs(directory, regex_pattern,
                         month_col=None, sales_col=None,
                         file_encoding='utf-8',
                         figsize=(10, 6),
                         show=True, save_path=None):
    """
    Search 'directory' for .csv files whose filenames match 'regex_pattern',
    read sales data from each matched CSV, and plot month (x-axis) vs sales (y-axis).
    Each CSV file that matches is plotted as a separate line labeled by filename.

    Parameters:
    - directory (str): Directory path to search for CSV files.
    - regex_pattern (str): Regular expression applied to filenames to select CSV files.
    - month_col (str or int, optional): If CSVs have headers, provide the column name for months.
                                        If CSVs have no header, provide column index (0-based) for months.
                                        If None, the function will try to auto-detect.
    - sales_col (str or int, optional): Column name or index for sales. If None, auto-detect.
    - file_encoding (str): File encoding for reading CSVs. Default 'utf-8'.
    - figsize (tuple): Figure size for the plot.
    - show (bool): Whether to call plt.show() at the end.
    - save_path (str, optional): If provided, save the figure to this path.

    Returns:
    - fig, ax: Matplotlib figure and axes objects.

    Notes:
    - Expected CSV layout: two columns (month, sales) or named columns containing month/date and sales values.
      Month values accepted: month names ('Jan', 'January'), month numbers ('1', '01'), date strings ('2021-01' or '2021-01-15'),
      or month+year formats. Sales values should be numeric (commas and currency symbols are stripped).
    - If multiple files have different month ranges, the x-axis will show the union of months; series that don't have a value for a month
      will simply not have a point at that month.
    """

    # --- Helpers ---
    def list_matching_csvs(dirpath, pattern):
        p = re.compile(pattern)
        files = []
        for fn in os.listdir(dirpath):
            if fn.lower().endswith('.csv') and p.search(fn):
                files.append(os.path.join(dirpath, fn))
        return sorted(files)

    def try_parse_month(value):
        """Return a datetime.date-like (datetime) representing the month (use day=1).
           If parse fails, return None.
        """
        if value is None:
            return None
        s = str(value).strip()
        if s == '':
            return None
        # Remove ordinal suffixes and stray characters
        s_clean = s.replace('.', '').replace(',', '').strip()
        # Try numeric month or month number with year
        # If it's a plain integer 1-12
        try:
            iv = int(s_clean)
            if 1 <= iv <= 12:
                return datetime(2000, iv, 1)
        except Exception:
            pass
        # Try YYYY-MM or YYYY-MM-DD
        date_formats = ['%Y-%m-%d', '%Y-%m', '%Y/%m/%d', '%Y/%m', '%m/%d/%Y', '%d/%m/%Y',
                        '%b %Y', '%B %Y', '%Y']
        for fmt in date_formats:
            try:
                dt = datetime.strptime(s_clean, fmt)
                # Normalize to first of month
                return datetime(dt.year, dt.month if hasattr(dt, 'month') else 1, 1)
            except Exception:
                pass
        # Try month name or abbreviation (with optional year)
        tokens = s_clean.split()
        # If token is like 'Jan' or 'January' or 'Jan-2021' or 'Jan2021'
        # Try to extract a three-letter month name
        for mon in range(1, 13):
            if s_clean.lower().startswith(calendar.month_name[mon].lower()) or \
               s_clean.lower().startswith(calendar.month_abbr[mon].lower()):
                # try to find a year in the string
                year = 2000
                digits = re.search(r'(\d{4})', s_clean)
                if digits:
                    year = int(digits.group(1))
                return datetime(year, mon, 1)
        # try patterns like 'Jan-21' or 'Jan21'
        m = re.match(r'([A-Za-z]{3,9})[^\d]*(\d{2,4})$', s_clean)
        if m:
            monname, y = m.groups()
            for mon in range(1, 13):
                if monname.lower().startswith(calendar.month_name[mon].lower()[:len(monname)]):
                    yy = int(y)
                    if yy < 100:
                        yy += 2000
                    return datetime(yy, mon, 1)
        return None

    def parse_sales_value(s):
        if s is None:
            return None
        s2 = str(s).strip()
        if s2 == '':
            return None
        # strip currency symbols and commas
        s2 = re.sub(r'[^\d\.\-eE]', '', s2)
        try:
            return float(s2)
        except Exception:
            return None

    def detect_header_and_read(path):
        """Return list of rows (as lists) and header (list of column names or None)."""
        with open(path, 'r', encoding=file_encoding, newline='') as f:
            sample = f.read(4096)
            f.seek(0)
            has_header = False
            try:
                has_header = csv.Sniffer().has_header(sample)
            except Exception:
                has_header = False
            reader = csv.reader(f)
            rows = list(reader)
            if has_header and len(rows) >= 1:
                header = [h.strip() for h in rows[0]]
                data_rows = rows[1:]
                return header, data_rows
            else:
