                        num_ok += 1
                numeric_score.append(num_ok / max(1, len(samples)))
            # assume sales_col is the column with highest numeric_score
            sales_idx = max(range(ncols), key=lambda i: numeric_score[i])
            # month candidate: choose a column with low numeric_score
            month_idx = None
