                    numeric_score.append(num_ok / max(1, len(samples)))
                if s_idx is None:
                    s_idx = max(range(ncols), key=lambda i: numeric_score[i])
                if m_idx is None:
                    # choose column with many parseable months
                    month_scores = []
                    for samples in col_samples:
                        m_ok = 0
                        for x in samples:
                            if try_parse_month(x) is not None:
                                m_ok += 1
                        month_scores.append(m_ok / max(1, len(samples)))
                    m_idx = max(range(ncols), key=lambda i: month_scores[i])
            return m_idx, s_idx, True

    # --- Main logic ---
    files = list_matching_csvs(directory, regex_pattern)
    if not files:
        raise FileNotFoundError(f"No CSV files matching pattern '{regex_pattern}' found in directory '{directory}'")

    series_list = []  # list of (label, list of (datetime, sales))
    for path in files:
        header, rows = detect_header_and_read(path)
        if not rows:
            # empty file
            continue
        m_idx, s_idx, header_present = pick_columns(header, rows)
        # iterate rows and extract (date, sales)
        points = []
        for r in rows:
            # guard
            if m_idx >= len(r) and s_idx >= len(r):
                continue
            mval = r[m_idx] if m_idx < len(r) else ''
            sval = r[s_idx] if s_idx < len(r) else ''
            dt = try_parse_month(mval)
            val = parse_sales_value(sval)
            # If dt is None but mval might be like just month names without year -> try again
            if dt is None:
                dt = try_parse_month(mval)
            if dt is not None and val is not None:
                points.append((dt, val))
        if not points:
            # try swapping columns (in case detection failed)
            alt_points = []
            for r in rows:
                a = r[s_idx] if s_idx < len(r) else ''
                b = r[m_idx] if m_idx < len(r) else ''
                dt2 = try_parse_month(a)
                val2 = parse_sales_value(b)
                if dt2 is not None and val2 is not None:
                    alt_points.append((dt2, val2))
            if alt_points:
                points = alt_points
        if points:
            # sort by datetime
            points.sort(key=lambda x: x[0])
            series_list.append((os.path.basename(path), points))

    if not series_list:
        raise ValueError("No parseable (month, sales) data found in matched CSV files.")

    # Prepare plot
    fig, ax = plt.subplots(figsize=figsize)
    for label, pts in series_list:
        xs = [p[0] for p in pts]
        ys = [p[1] for p in pts]
        ax.plot(xs, ys, marker='o', label=label)

    # Format x-axis: use Month locator and formatter
    # Determine min/max date to set locator
    all_x = sorted({dt for _, pts in series_list for dt, _ in pts})
    if not all_x:
        raise ValueError("No x-values to plot.")
    min_dt = all_x[0]
    max_dt = all_x[-1]
    # If span <= 365 days, show month ticks.
    span_days = (max_dt - min_dt).days if isinstance(min_dt, datetime) else 0
    if span_days <= 366:
        ax.xaxis.set_major_locator(mdates.MonthLocator())
        # If same year for all points, display month abbreviation; else month + year
        years = {dt.year for dt in all_x}
        if len(years) == 1:
            ax.xaxis.set_major_formatter(mdates.DateFormatter('%b'))
        else:
            ax.xaxis.set_major_formatter(mdates.DateFormatter('%b %Y'))
    else:
        # for multi-year data, show every 3 months or yearly depending on span
        ax.xaxis.set_major_locator(mdates.AutoDateLocator())
        ax.xaxis.set_major_formatter(mdates.DateFormatter('%b %Y'))

    ax.set_xlabel('Month')
    ax.set_ylabel('Sales')
    ax.set_title('Sales by Month')
    ax.legend()
    ax.grid(True)
    fig.autofmt_xdate()

    if save_path:
        fig.savefig(save_path, bbox_inches='tight')

    if show:
        plt.show()

    return fig, ax

