Here's a single self-contained Python function that searches a directory for CSV files whose filenames match a given regular-expression, reads month and sales columns from those files, aggregates sales by year-month, and plots sales (month on x-axis, sales on y-axis). It uses only the Python standard library plus matplotlib (lightweight for plotting).

Usage notes:
- By default it looks for columns named "month" (or "date") and "sales" (case-insensitive). You can override column names with month_col and sales_col.
- It attempts to parse a wide range of common date formats (e.g., "2020-01", "2020-01-15", "Jan 2020", "01/2020", etc.). The aggregated x-axis is by year-month (YYYY-MM).
- You can aggregate across files by sum (default) or mean.
- Set recursive=True to search subdirectories.

Code:

```python
def plot_sales_from_csvs(directory,
                         pattern,
                         month_col='month',
                         sales_col='sales',
                         recursive=False,
                         aggregate='sum',   # 'sum' or 'mean'
                         save_path=None,    # optionally save the plot to a file
                         show=True,
                         figsize=(10, 6)):
    """
    Search directory for CSV files whose filenames match the given regex 'pattern',
    read sales data (month/date and sales) from them, aggregate by year-month,
    and plot month (x-axis) vs sales (y-axis).

    Parameters:
    - directory: path to directory to search
    - pattern: regular expression to match filenames (applied to filename)
    - month_col: name of the column containing months/dates (case-insensitive)
    - sales_col: name of the column containing sales numbers (case-insensitive)
    - recursive: if True, search subdirectories
    - aggregate: 'sum' or 'mean' when combining rows with the same month
    - save_path: if provided, save the plot to this path (e.g., 'out.png')
    - show: if True, call plt.show()
    - figsize: tuple for figure size

    Returns:
    - fig, ax, aggregated_dict where aggregated_dict maps 'YYYY-MM' -> aggregated value
    """
    import os
    import re
    import csv
    import datetime
    from collections import defaultdict
    import math
    import warnings

    # matplotlib is the only non-stdlib dependency (lightweight for plotting)
    import matplotlib.pyplot as plt
    import matplotlib.dates as mdates

    # Helper: find matching key in a list of fieldnames (case-insensitive)
    def find_field(fieldnames, target):
        if not fieldnames:
            return None
        target_lower = target.lower()
        for f in fieldnames:
            if f and f.lower() == target_lower:
                return f
        # fallback: try some common synonyms
        synonyms = {
            'month': ['date', 'period', 'month'],
            'sales': ['revenue', 'amount', 'total', 'sale']
        }
        for f in fieldnames:
            if f and any(f.lower() == s for s in synonyms.get(target_lower, [])):
                return f
        return None

    # Helper: parse a sales string into float
    def parse_sales(s):
        if s is None:
            return None
        s = str(s).strip()
        if s == '':
            return None
        # remove currency signs, commas, spaces; handle parentheses for negative
        neg = False
        if s.startswith('(') and s.endswith(')'):
            neg = True
            s = s[1:-1]
        s = re.sub(r'[^\d\.\-eE]', '', s)  # allow digits, dot, minus, exponent
        try:
            val = float(s)
            if neg:
                val = -val
            if math.isfinite(val):
                return val
            return None
        except Exception:
            return None

    # Helper: try parsing various date formats into a datetime.date
    def try_parse_date(s):
        if s is None:
            return None
        s = str(s).strip()
        if s == '':
            return None
        # if it's just a year-month like YYYY-MM or YYYY/MM or YYYY.MM
        s_clean = s.replace('/', '-').replace('.', '-')
        # common formats to try
        fmts = [
            '%Y-%m-%d', '%Y-%m', '%Y%m', '%Y',
            '%d-%b-%Y', '%d-%B-%Y', '%b %Y', '%B %Y',
            '%m/%Y', '%m/%d/%Y', '%m-%d-%Y',
            '%Y/%m/%d', '%Y.%m.%d', '%Y.%m',
        ]
        # Also allow ISO-like full datetime
        iso_try = None
        try:
            # datetime.fromisoformat accepts many ISO forms (Python 3.7+)
            iso_try = datetime.datetime.fromisoformat(s)
            if isinstance(iso_try, datetime.datetime):
                return iso_try.date()
        except Exception:
            pass

        for fmt in fmts:
            try:
                dt = datetime.datetime.strptime(s_clean, fmt)
                # if format provided only year or year-month, ensure a day exists
                if fmt == '%Y' or fmt == '%Y%m':
                    return datetime.date(dt.year, 1, 1)
                if fmt == '%Y-%m':
                    return datetime.date(dt.year, dt.month, 1)
                if fmt == '%b %Y' or fmt == '%B %Y' or fmt == '%m/%Y':
                    return datetime.date(dt.year, dt.month, 1)
                return dt.date()
            except Exception:
                continue

        # Handle plain month names like "January" or "Jan" -> assume current year
        try:
            month_names = {m.lower(): i for i, m in enumerate(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'], start=1)}
            s_lower = s.strip().lower()
            for k, v in month_names.items():
                if s_lower.startswith(k.lower()):
                    year = datetime.date.today().year
                    return datetime.date(year, v, 1)
        except Exception:
            pass

        return None

    # Find files
    compiled = re.compile(pattern)
    matched_files = []
    if recursive:
        for root, dirs, files in os.walk(directory):
            for fn in files:
                if fn.lower().endswith('.csv') and compiled.search(fn):
                    matched_files.append(os.path.join(root, fn))
    else:
        for fn in os.listdir(directory):
            path = os.path.join(directory, fn)
            if os.path.isfile(path) and fn.lower().endswith('.csv') and compiled.search(fn):
                matched_files.append(path)

    if not matched_files:
        raise FileNotFoundError(f"No CSV files matching pattern '{pattern}' found in '{directory}' (recursive={recursive}).")

    # aggregate store: either sum (float) or list (for mean)
    if aggregate not in ('sum', 'mean'):
        raise ValueError("aggregate must be 'sum' or 'mean'")

    agg = defaultdict(float) if aggregate == 'sum' else defaultdict(list)
    any_row = False

    for fp in matched_files:
        try:
            with open(fp, newline='', encoding='utf-8', errors='replace') as fh:
                reader = csv.DictReader(fh)
                if reader.fieldnames is None:
                    warnings.warn(f"No header detected in CSV: {fp} -- skipping")
                    continue
                mc = find_field(reader.fieldnames, month_col)
                sc = find_field(reader.fieldnames, sales_col)
                if mc is None or sc is None:
                    warnings.warn(f"Could not find month/date or sales column in '{fp}'. "
                                  f"Searched for '{month_col}' and '{sales_col}'. Found fields: {reader.fieldnames}. Skipping file.")
                    continue

                for row in reader:
                    mval = row.get(mc)
                    sval = row.get(sc)
                    d = try_parse_date(mval)
                    s = parse_sales(sval)
                    if d is None or s is None:
                        # skip rows that can't be parsed
                        continue
                    any_row = True
                    key = d.strftime('%Y-%m')
                    if aggregate == 'sum':
                        agg[key] += s
                    else:
                        agg[key].append(s)
        except Exception as e:
            warnings.warn(f"Failed to read '{fp}': {e}. Skipping file.")

    if not any_row:
        raise ValueError("No parsable rows found (did not find any valid month/date + sales pairs).")

    # If mean, compute means
    final_agg = {}
    if aggregate == 'sum':
        final_agg = dict(agg)
    else:
        for k, lst in agg.items():
            if lst:
                final_agg[k] = sum(lst) / len(lst)

    # Sort keys chronologically
    def key_to_date(k):
        try:
            return datetime.datetime.strptime(k, '%Y-%m').date()
        except Exception:
            # fallback minimal parse
            parts = k.split('-')
            if len(parts) >= 2:
                return datetime.date(int(parts[0]), int(parts[1]), 1)
            return datetime.date.today()

    items = sorted(final_agg.items(), key=lambda kv: key_to_date(kv[0]))
    if not items:
        raise ValueError("No aggregated items to plot after processing.")

    x_dates = [key_to_date(k) for k, _ in items]
    y_vals = [v for _, v in items]

    # Plotting
    fig, ax = plt.subplots(figsize=figsize)
    ax.plot(x_dates, y_vals, marker='o', linestyle='-')
    ax.set_xlabel('Month')
    ax.set_ylabel('Sales')
    ax.set_title(f"Sales by month ({aggregate}) from {len(matched_files)} file(s) matching /{pattern}/")

    # format x-axis as year-month
    ax.xaxis.set_major_locator(mdates.AutoDateLocator())
    ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y-%m'))
    fig.autofmt_xdate(rotation=45, ha='right')

    # grid and tight layout
    ax.grid(True, linestyle='--', alpha=0.4)
    fig.tight_layout()

    if save_path:
        try:
            fig.savefig(save_path, bbox_inches='tight')
        except Exception as e:
            warnings.warn(f"Failed to save figure to '{save_path}': {e}")

    if show:
        plt.show()

    return fig, ax, final_agg
```

