Here's a self-contained Python function that extracts numerical data from a JSON-like structure given a path of keys and visualizes it with matplotlib (a lightweight, commonly available plotting library). The function accepts either a Python dict/list or a JSON string as input. The path can be specified as a dotted string using optional list indices (e.g. "a.b[0].c") and supports a wildcard "[*]" to iterate all items in lists/dicts at that step.

Copy-paste this function into your code and call it as shown in the examples in the docstring.

```python
import json
import re
import numbers
import matplotlib.pyplot as plt
from typing import Any, List, Tuple, Optional

def extract_and_plot(json_input: Any,
                     key_path: Any,
                     plot_type: str = 'line',
                     bins: int = 30,
                     figsize: Tuple[int, int] = (8, 4),
                     title: Optional[str] = None,
                     xlabel: Optional[str] = None,
                     ylabel: Optional[str] = None,
                     save_path: Optional[str] = None,
                     show: bool = True) -> Tuple[List[float], plt.Figure]:
    """
    Extract numerical values from a JSON-like structure following key_path and plot them.

    Parameters:
    - json_input: dict/list or JSON string containing the data.
    - key_path: path to extract values. Either:
        - a list of keys/indices/wildcards, e.g. ['a', 0, 'c']
        - or a string like "a.b[0].c" or "a.items[*].value" (use [*] as wildcard)
    - plot_type: one of 'line', 'hist', 'bar', 'scatter' (default 'line').
    - bins: for histogram (default 30).
    - figsize: tuple for figure size (default (8,4)).
    - title, xlabel, ylabel: labels for the plot.
    - save_path: if given, saves the figure to this file path.
    - show: if True, calls plt.show(); otherwise returns the figure without showing.

    Returns:
    - (values, figure) where values is the extracted list of floats and figure is the Matplotlib Figure.

    Notes:
    - The function recursively collects numeric scalars (ints/floats).
    - Non-numeric entries are ignored.
    - If no numeric values are found, ValueError is raised.

    Examples:
    data = {
        "series": [
            {"time": 1, "value": 2.5},
            {"time": 2, "value": 3.1},
            {"time": 3, "value": 4.0}
        ]
    }
    # Extract all "value" entries from series:
    vals, fig = extract_and_plot(data, "series[*].value", plot_type='line', title="Values")

    # Using a JSON string and histogram:
    json_str = '{"nums": [1,2,3,4,5,6]}'
    vals, fig = extract_and_plot(json_str, "nums", plot_type='hist', bins=6)
    """
    # Helper: parse path string into tokens
    def parse_path(path):
        if isinstance(path, list):
            return path
        if not isinstance(path, str):
            raise TypeError("key_path must be a list or string")
        tokens = []
        # regex finds either key names or [index] or [*]
        pattern = re.compile(r'([^\.\[\]]+)|\[(\*|\d+)\]')
        for match in pattern.finditer(path):
            name, idx = match.groups()
            if name is not None:
                tokens.append(name)
            else:
                if idx == '*':
                    tokens.append('*')
                else:
                    tokens.append(int(idx))
        return tokens

    # Helper: recursively collect numeric scalars from any nested structure
    def collect_numbers(obj):
        out = []
        if isinstance(obj, numbers.Number):
            out.append(float(obj))
        elif isinstance(obj, dict):
            for v in obj.values():
                out.extend(collect_numbers(v))
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                out.extend(collect_numbers(v))
        # else: ignore non-numeric leaf
        return out

    # Traverser: follow tokens, supporting wildcard '*' for lists/dicts
    def traverse(obj, tokens, pos=0):
        if pos >= len(tokens):
            return collect_numbers(obj)
        token = tokens[pos]
        results = []
        if token == '*':
            # iterate over all elements (if list) or all values (if dict)
            if isinstance(obj, dict):
                for v in obj.values():
                    results.extend(traverse(v, tokens, pos + 1))
            elif isinstance(obj, (list, tuple)):
                for v in obj:
                    results.extend(traverse(v, tokens, pos + 1))
            # else: nothing to iterate
        elif isinstance(token, int):
            # index into list/tuple
            if isinstance(obj, (list, tuple)):
                if 0 <= token < len(obj):
                    results.extend(traverse(obj[token], tokens, pos + 1))
            # else: can't index
        else:
            # string key for dict
            if isinstance(obj, dict) and token in obj:
                results.extend(traverse(obj[token], tokens, pos + 1))
        return results

    # Parse input JSON if needed
    if isinstance(json_input, str):
        try:
            data = json.loads(json_input)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON string: {e}")
    else:
        data = json_input

    tokens = parse_path(key_path)
    values = traverse(data, tokens)

    if not values:
        raise ValueError("No numeric values found for the given path.")

    # Plotting
    fig, ax = plt.subplots(figsize=figsize)
    if plot_type == 'line':
        ax.plot(list(range(len(values))), values, marker='o')
    elif plot_type == 'hist':
        ax.hist(values, bins=bins)
    elif plot_type == 'bar':
        ax.bar(list(range(len(values))), values)
    elif plot_type == 'scatter':
        ax.scatter(list(range(len(values))), values)
    else:
        plt.close(fig)
        raise ValueError(f"Unsupported plot_type '{plot_type}'. Use 'line', 'hist', 'bar', or 'scatter'.")

    if title:
        ax.set_title(title)
    if xlabel:
        ax.set_xlabel(xlabel)
    if ylabel:
        ax.set_ylabel(ylabel)

    ax.grid(True)

    if save_path:
        fig.savefig(save_path, bbox_inches='tight')

    if show:
        plt.show()
    else:
        plt.close(fig)  # don't leave the window open in non-interactive contexts

    return values, fig
