    # We return a list of tuples (value, context_node). context_node is the node at which the wildcard matched
    # (or the node that yielded the numeric leaf if no wildcard used).
    def extract_with_context(node, toks):
        if not toks:
            # If no tokens left: collect numeric leaves under node
            results = []
            if is_number(node):
                results.append((node, node))
            elif isinstance(node, Mapping):
                for v in node.values():
                    results.extend(extract_with_context(v, []))
            elif isinstance(node, Sequence) and not isinstance(node, (str, bytes)):
                for v in node:
                    results.extend(extract_with_context(v, []))
            return results

        tok = toks[0]
        rest = toks[1:]

        if tok == '*':
            results = []
            if isinstance(node, Mapping):
                for k, v in node.items():
                    # for wildcard we consider the matched element's node to be v (the value)
                    results.extend(extract_with_context(v, rest) or [])
                return results
            elif isinstance(node, Sequence) and not isinstance(node, (str, bytes)):
                for v in node:
                    results.extend(extract_with_context(v, rest) or [])
                return results
            else:
                return []  # nothing to iterate

        # try numeric index for lists
        if isinstance(node, Sequence) and not isinstance(node, (str, bytes)):
            # token may be an integer index
            try:
                idx = int(tok)
            except Exception:
                return []  # can't index sequence by non-integer token
            if idx < 0 or idx >= len(node):
                return []
            return extract_with_context(node[idx], rest)

        # mapping / dict access
        if isinstance(node, Mapping):
            if tok in node:
                return extract_with_context(node[tok], rest)
            else:
                return []
        # otherwise no match
        return []

    # run extraction
    extracted = extract_with_context(data, tokens)
    values = [v for v, _ in extracted]

    if not values:
        raise ValueError("No numeric values found for the provided key_path.")

    # build labels if requested and possible
    labels = None
    if label_tokens is not None and extracted:
        # For each context node, try to resolve label_tokens relative to that context
        def resolve_label(ctx_node, toks):
            n = ctx_node
