                    if isinstance(n, Mapping):
                        # pick first value
                        if n:
                            n = next(iter(n.values()))
                        else:
                            return None
                    elif isinstance(n, Sequence) and not isinstance(n, (str, bytes)):
                        if n:
                            n = n[0]
                        else:
                            return None
                    else:
                        return None
                else:
                    if isinstance(n, Mapping):
                        n = n.get(t, None)
                    elif isinstance(n, Sequence) and not isinstance(n, (str, bytes)):
                        try:
                            idx = int(t)
                            n = n[idx] if 0 <= idx < len(n) else None
                        except Exception:
                            return None
                    else:
                        return None
                    if n is None:
                        return None
            # at end, if primitive, return str; if number return as is; else attempt to stringify
            if n is None:
                return None
            if isinstance(n, (str, int, float, bool)):
