from typing import Any, List, Union, Sequence, Tuple, Optional
import numbers

def extract_and_visualize(
    json_obj: Any,
    key_path: Union[str, Sequence[Union[str, int]]],
    chart: str = "hist",
    bins: int = 30,
    figsize: Tuple[int, int] = (8, 4),
    title: Optional[str] = None,
    xlabel: Optional[str] = None,
    ylabel: Optional[str] = None,
    show: bool = True,
    save_path: Optional[str] = None,
) -> List[float]:
    """
    Extract numerical data from a JSON-like structure following `key_path` and visualize it.

    Parameters
    - json_obj: the JSON-like object (nested dicts/lists).
    - key_path: either:
        - a dot-separated string of keys, e.g. "a.b.*.value" where "*" means "all elements"
        - or a sequence/list of keys/indices, e.g. ["a", "b", "*", "value"]
      If a list is encountered while the next key is a literal string (not "*"), the function will
      try to apply that key to each dict element of the list when appropriate.
      Numeric list indices may be given (e.g. "items.0.value" or ["items", 0, "value"]).
    - chart: one of "hist" (histogram), "line" (line plot), or "box" (boxplot). Default "hist".
    - bins: number of bins for histogram.
    - figsize: size of the matplotlib figure (width, height).
    - title, xlabel, ylabel: optional labels.
    - show: whether to call plt.show() (ignored for ASCII fallback).
    - save_path: if given, save the plot image to this path.

    Returns:
    - List[float]: the extracted numeric values (possibly empty).

    Notes:
    - If matplotlib is not available, the function will print a small ASCII histogram instead.
    - Non-numeric leaf nodes are ignored.
    - Example usage:
        data = {
            "series": [
                {"value": 1.2}, {"value": 3.4}, {"value": 2.1}
            ],
            "meta": {"x": 100}
        }
        nums = extract_and_visualize(data, "series.*.value", chart="hist")
    """
    # Normalize key_path to list of strings/ints
    if isinstance(key_path, str):
        # split on dots
        parts = key_path.split(".") if key_path != "" else []
        # convert integer-like parts to int
        def _conv(p):
            if p == "*":
                return "*"
            try:
                return int(p)
            except Exception:
                return p
        parts = [_conv(p) for p in parts]
    else:
        # assume sequence
        parts = []
        for p in key_path:
            if p == "*":
                parts.append("*")
            elif isinstance(p, str):
                try:
                    parts.append(int(p))
                except Exception:
                    parts.append(p)
            else:
                parts.append(p)

    collected: List[float] = []

    def collect_numbers(node: Any):
        """Recursively collect numeric leaf values from node into collected."""
        if node is None:
            return
        if isinstance(node, numbers.Number) and not isinstance(node, bool):
            collected.append(float(node))
        elif isinstance(node, dict):
            for v in node.values():
                collect_numbers(v)
        elif isinstance(node, (list, tuple)):
            for item in node:
                collect_numbers(item)
        # else: ignore non-numeric primitives (str, bool, etc.)

    def traverse(node: Any, path_parts: List[Any]):
        if node is None:
            return
        if not path_parts:
            # reached target: collect numbers under this node
            collect_numbers(node)
            return

        part = path_parts[0]
        rest = path_parts[1:]

        # wildcard: iterate through dict values and list items
        if part == "*":
            if isinstance(node, dict):
                for v in node.values():
                    traverse(v, rest)
            elif isinstance(node, (list, tuple)):
                for item in node:
                    traverse(item, rest)
            # else nothing to iterate
            return

        # If node is dict and part is a key
        if isinstance(node, dict):
            if part in node:
                traverse(node[part], rest)
            else:
                # nothing else to do
                return
            return

        # If node is a list/tuple
        if isinstance(node, (list, tuple)):
            # if part is an integer index, try direct indexing
            if isinstance(part, int):
                idx = part
                if 0 <= idx < len(node):
                    traverse(node[idx], rest)
                return
            # If part is string, attempt:
            # 1) If items are dicts and have that key, apply to each such item.
            for item in node:
                if isinstance(item, dict) and part in item:
                    traverse(item[part], rest)
                # Also if item itself matches the key (rare), e.g., list of primitives and part equals "*"? skip
            return

        # otherwise nothing to do
        return

    traverse(json_obj, parts)

    # Visualization
    try:
        import matplotlib.pyplot as plt  # type: ignore
        has_plt = True
    except Exception:
        has_plt = False

    if not collected:
        # nothing found; return early but still attempt to show empty plot if requested
        if has_plt:
            plt.figure(figsize=figsize)
            plt.text(0.5, 0.5, "No numeric data found for path", ha="center", va="center")
            plt.axis("off")
            if title:
                plt.title(title)
            if save_path:
                plt.savefig(save_path, bbox_inches="tight")
            if show:
                plt.show()
        else:
            print("No numeric data found for path.")
        return collected

    if has_plt:
        plt.figure(figsize=figsize)
        if chart == "hist":
            plt.hist(collected, bins=bins, edgecolor="black")
            if ylabel is None:
                ylabel = "Count"
        elif chart == "line":
            plt.plot(collected, marker="o")
            if ylabel is None:
                ylabel = "Value"
        elif chart == "box":
            plt.boxplot(collected, vert=True)
            if ylabel is None:
                ylabel = "Value"
        else:
            # fallback to histogram
            plt.hist(collected, bins=bins, edgecolor="black")
            if ylabel is None:
                ylabel = "Count"

        if title:
            plt.title(title)
        else:
            plt.title(f"Extracted {len(collected)} numeric values")
        if xlabel:
            plt.xlabel(xlabel)
        if ylabel:
            plt.ylabel(ylabel)

        if save_path:
            plt.savefig(save_path, bbox_inches="tight")
        if show:
            plt.show()
        else:
            plt.close()
    else:
        # ASCII fallback: simple histogram-like summary
        try:
            import statistics as _stats
            mn = _stats.mean(collected)
            med = _stats.median(collected)
            sd = _stats.pstdev(collected) if len(collected) > 1 else 0.0
        except Exception:
            mn = med = sd = None
        print(f"Extracted {len(collected)} numeric values. mean={mn} median={med} std={sd}")
        # simple textual histogram (10 buckets)
        lo, hi = min(collected), max(collected)
        if lo == hi:
            print(f"All values equal: {lo}")
        else:
            buckets = 10
            counts = [0] * buckets
            span = hi - lo
            for v in collected:
                i = int((v - lo) / span * (buckets - 1e-9))
                if i < 0:
                    i = 0
                elif i >= buckets:
                    i = buckets - 1
                counts[i] += 1
            maxc = max(counts)
            for i, c in enumerate(counts):
                left = lo + i * span / buckets
                right = lo + (i + 1) * span / buckets
                bar = "#" * int((c / maxc) * 40)
                print(f"{left:8.3f} - {right:8.3f} | {bar} ({c})")

    return collected
