def extract_text_from_image(path,
                            target_encoding='utf-8',
                            tesseract_lang=None,
                            return_bytes=False,
                            ocr_config='--psm 3'):
    """
    Open an image, extract text using OCR (pytesseract) when available, normalize/convert encoding,
    and fall back to image comment/metadata extraction if OCR yields no result.

    Parameters:
    - path: str or file-like object path to image.
    - target_encoding: encoding to use if return_bytes True (default 'utf-8').
    - tesseract_lang: language string for pytesseract (e.g. 'eng'); None uses pytesseract default.
    - return_bytes: if True, return bytes encoded with target_encoding; otherwise return Python str.
    - ocr_config: additional config string passed to pytesseract.image_to_string (default '--psm 3').

    Returns:
    - str (Unicode) by default, or bytes when return_bytes=True.
    - Returns empty string / b'' if nothing found.
    """
    from PIL import Image
    try:
        import pytesseract
        from pytesseract import TesseractError
        pytesseract_available = True
    except Exception:
        pytesseract_available = False
        TesseractError = Exception  # fallback for except blocks

    # Optional encoding detector
    try:
        import chardet
        _use_chardet = True
    except Exception:
        chardet = None
        _use_chardet = False

    def _decode_bytes(b):
        """Try to decode bytes to str using a few heuristics, optionally using chardet."""
        if b is None:
            return ''
        if isinstance(b, str):
            return b
        if not isinstance(b, (bytes, bytearray)):
            try:
                return str(b)
            except Exception:
                return ''
        # Try utf-8
        for enc in ('utf-8', 'utf-8-sig', 'utf-16', 'utf-16le', 'utf-16be', 'iso-8859-1', 'latin-1'):
            try:
                return b.decode(enc)
            except Exception:
                pass
        # If chardet available, use it
        if _use_chardet:
            try:
                res = chardet.detect(b)
                enc = res.get('encoding')
                if enc:
                    return b.decode(enc, errors='replace')
            except Exception:
                pass
        # Last resort: latin-1 fallback (preserves bytes 1:1)
        try:
            return b.decode('latin-1', errors='replace')
        except Exception:
            return b.decode('utf-8', errors='replace')

    def _extract_comment_from_image(img):
        """Look through possible metadata/comment locations and return text if any."""
        # 1) EXIF UserComment (tag 0x9286 = 37510)
        try:
            exif = img.getexif()
            if exif:
                uc = exif.get(37510)  # UserComment
                if uc:
                    # EXIF UserComment often has an 8-byte prefix indicating encoding
                    if isinstance(uc, bytes):
                        prefix = uc[:8]
                        body = uc[8:]
                        if prefix.startswith(b'ASCII'):
                            return _decode_bytes(body.split(b'\x00', 1)[0])
                        if prefix.startswith(b'UNICODE'):
                            # EXIF uses UTF-16 for "UNICODE"
                            try:
                                return body.decode('utf-16', errors='replace')
                            except Exception:
                                return _decode_bytes(body)
                        if prefix.startswith(b'JIS'):
                            try:
                                return body.decode('shift_jis', errors='replace')
                            except Exception:
                                return _decode_bytes(body)
                        # No known prefix
                        return _decode_bytes(uc)
                    else:
                        return _decode_bytes(uc)
        except Exception:
            pass

        # 2) Generic image.info keys (PNG tEXt, iTXt, JPEG comment, etc.)
        try:
            info = getattr(img, 'info', {}) or {}
            # If info keys contain string values already, prefer those
            # Collect candidate values
            candidates = []
            for k, v in info.items():
                # Some libraries put PNG text chunks under 'text' or 'description'
                if isinstance(v, (str,)):
                    candidates.append(v)
                elif isinstance(v, (bytes, bytearray)):
                    candidates.append(_decode_bytes(v))
                else:
                    # try to stringify
                    try:
                        candidates.append(str(v))
                    except Exception:
                        pass
            # JPEG may have a 'comment' entry as bytes
            comment = info.get('comment') or info.get('Comment')
            if isinstance(comment, (bytes, bytearray)):
                candidates.insert(0, _decode_bytes(comment))
            # Return the first non-empty candidate
            for c in candidates:
                if c:
                    return c
        except Exception:
            pass

        # 3) Some images may store XMP or other XML metadata under keys like "XML:com.adobe.xmp"
        try:
            info = getattr(img, 'info', {}) or {}
            for k in info:
                if 'xmp' in str(k).lower() or 'xml' in str(k).lower():
                    v = info[k]
                    if isinstance(v, (bytes, bytearray)):
                        return _decode_bytes(v)
                    else:
                        return _decode_bytes(str(v))
        except Exception:
            pass

        return ''

    # Open image
    try:
        img = Image.open(path)
    except Exception as e:
        raise IOError(f"Cannot open image {path!r}: {e}")

    text = ''
    # Try OCR if pytesseract available
    if pytesseract_available:
        try:
            # pytesseract expects either PIL Image or OpenCV image
            # tesseract_lang may be None (defaults)
            if tesseract_lang:
                text = pytesseract.image_to_string(img, lang=tesseract_lang, config=ocr_config)
            else:
                text = pytesseract.image_to_string(img, config=ocr_config)
            if isinstance(text, bytes):
                text = _decode_bytes(text)
            text = text.strip()
        except (TesseractError, FileNotFoundError, RuntimeError) as e:
            # Tesseract binary missing or other error; ignore and fall back
            text = ''
        except Exception:
            # any other OCR problems -> fall back
            text = ''

    # If OCR gave nothing, fallback to comments/metadata
    if not text:
        try:
            text = _extract_comment_from_image(img).strip()
        except Exception:
            text = ''

    # Normalize line endings and trim
    if isinstance(text, str):
        text = text.replace('\r\n', '\n').replace('\r', '\n').strip()
    else:
        text = str(text).strip()

    if return_bytes:
        try:
            return text.encode(target_encoding, errors='replace')
        except Exception:
            # if target encoding fails, fallback to utf-8
            return text.encode('utf-8', errors='replace')
    else:
        return text
```

Example usage:
- extract Unicode text (string): text = extract_text_from_image("photo.jpg")
- extract bytes in UTF-8: b = extract_text_from_image("photo.png", return_bytes=True, target_encoding="utf-8")
- ask OCR to use English: text = extract_text_from_image("scan.tif", tesseract_lang='eng')

