Below is a single self-contained Python function (with necessary imports) that:

- Opens an image file with Pillow
- Tries OCR via pytesseract
- If OCR yields nothing useful, falls back to extracting textual comments/metadata from the image
- Attempts to detect and normalize text encoding (using chardet when needed)
- Returns either a Unicode string or bytes encoded to a requested target encoding

Dependencies: pillow, pytesseract, chardet
Install with: pip install pillow pytesseract chardet

Function:

```python
from PIL import Image, ExifTags
import chardet

# pytesseract is optional only for OCR; fallback works using metadata/comments
try:
    import pytesseract
    _HAS_PYTESSERACT = True
except ImportError:
    pytesseract = None
    _HAS_PYTESSERACT = False


def extract_text_from_image(
    image_path,
    ocr_lang=None,
    target_encoding='utf-8',
    return_bytes=False,
    ocr_config=None,
):
    """
    Open an image, try OCR to extract text, and convert encoding.
    If OCR returns no useful text, fall back to reading image comments/metadata.

    Parameters:
    - image_path: path to image file
    - ocr_lang: language code for pytesseract (e.g. 'eng') or None
    - target_encoding: encoding to produce when return_bytes=True (default 'utf-8')
    - return_bytes: if True, return bytes encoded with target_encoding;
                    otherwise return a Python str (unicode)
    - ocr_config: optional string of extra config for pytesseract (e.g. '--psm 6')

    Returns:
    - a str (if return_bytes=False) or bytes (if return_bytes=True)
    - empty string/bytes if nothing found

    Raises:
    - RuntimeError if pytesseract is requested (present) but fails during OCR call.
    """

    def _safe_decode_bytes(bs):
        # Remove leading/trailing nulls and whitespace
        if not isinstance(bs, (bytes, bytearray)):
            return None
        bs = bytes(bs)
        # strip NULs at ends
        bs = bs.strip(b'\x00 \t\r\n')
        if not bs:
            return None

        # Try common encodings heuristically first
        for enc in ('utf-8', 'utf-16', 'utf-16le', 'utf-16be', 'cp1252', 'latin1'):
            try:
                s = bs.decode(enc)
                # if decode produced replacement characters too many, skip maybe
                # but be lenient: return first plausible decode
                if s and not all(ch == '\ufffd' for ch in s):
                    return s.strip('\x00')
            except Exception:
                pass

        # Use chardet as fallback
        try:
            det = chardet.detect(bs)
            enc = det.get('encoding')
            if enc:
                try:
                    s = bs.decode(enc, errors='replace')
                    return s.strip('\x00')
                except Exception:
                    pass
        except Exception:
            pass

        # Last resort: latin1 (lossless mapping)
        try:
            return bs.decode('latin1').strip('\x00')
        except Exception:
            return None

    def _collect_metadata_strings(img):
        candidates = []

        # Pillow's info dictionary may contain textual keys (PNG tEXt, JPEG comment)
        try:
            info = img.info or {}
            for k, v in info.items():
                if isinstance(v, str) and v.strip():
                    candidates.append(v)
                elif isinstance(v, (bytes, bytearray)) and v:
                    decoded = _safe_decode_bytes(v)
                    if decoded:
                        candidates.append(decoded)
        except Exception:
            pass

        # Exif tags that often store textual comments
        try:
            exif = img.getexif()
            if exif:
                for tag_id, value in exif.items():
                    tag_name = ExifTags.TAGS.get(tag_id, tag_id)
                    # Accept string values
                    if isinstance(value, str) and value.strip():
                        candidates.append(value)
                    elif isinstance(value, (bytes, bytearray)) and value:
                        # Many XP* tags are UTF-16LE; try decode heuristics
                        # If XP* tag name starts with 'XP' treat as utf-16le first
                        if isinstance(tag_name, str) and tag_name.startswith('XP'):
                            try:
                                s = bytes(value).decode('utf-16le', errors='strict')
                                if s.strip('\x00').strip():
                                    candidates.append(s.strip('\x00'))
                                    continue
                            except Exception:
                                pass
                        # UserComment in EXIF may have format prefix (e.g. "ASCII\0\0\0" or "UNICODE\0")
                        if isinstance(tag_name, str) and tag_name == 'UserComment':
                            b = bytes(value)
                            # If there's a known prefix, try to handle
                            if b.startswith(b'ASCII\x00\x00\x00'):
                                try:
                                    s = b[8:].decode('ascii', errors='replace')
                                    candidates.append(s)
                                    continue
                                except Exception:
                                    pass
                            if b.startswith(b'UNICODE\x00'):
                                try:
                                    s = b[8:].decode('utf-16', errors='replace')
                                    candidates.append(s)
                                    continue
                                except Exception:
                                    pass
                        decoded = _safe_decode_bytes(value)
                        if decoded:
                            candidates.append(decoded)
        except Exception:
            pass

        # Deduplicate preserving order
        seen = set()
        deduped = []
        for c in candidates:
            if c not in seen:
                seen.add(c)
                deduped.append(c)
        return deduped

    # Open image
    img = Image.open(image_path)

    text = ''
    # Try OCR first if pytesseract is available
    if _HAS_PYTESSERACT:
        try:
            rgb = img.convert('RGB')
            if ocr_lang and ocr_config:
                text = pytesseract.image_to_string(rgb, lang=ocr_lang, config=ocr_config)
            elif ocr_lang:
                text = pytesseract.image_to_string(rgb, lang=ocr_lang)
            elif ocr_config:
                text = pytesseract.image_to_string(rgb, config=ocr_config)
            else:
                text = pytesseract.image_to_string(rgb)
            if text:
                text = text.strip()
        except Exception as e:
            # If pytesseract fails for some reason, raise to let caller know
            raise RuntimeError("pytesseract OCR failed: %s" % str(e))

    # If OCR result is empty or only whitespace, fallback to metadata/comments
    if not text:
        meta_candidates = _collect_metadata_strings(img)
        if meta_candidates:
            # pick the first meaningful candidate
            for cand in meta_candidates:
                if cand and cand.strip():
                    text = cand.strip()
                    break

    # Final normalization: ensure text is a str
    if not isinstance(text, str):
        # If bytes, attempt decode
        if isinstance(text, (bytes, bytearray)):
            decoded = _safe_decode_bytes(text)
            text = decoded or ''
        else:
            text = str(text) if text is not None else ''

    # Return either unicode str or encoded bytes
    if return_bytes:
        try:
            return text.encode(target_encoding, errors='replace')
        except Exception:
            # If encoding fails, fallback to utf-8 with replace
            return text.encode('utf-8', errors='replace')
    else:
        return text
```

Example usage:
- Return Unicode string:
  text = extract_text_from_image("photo.jpg")
- Return UTF-8 bytes:
  b = extract_text_from_image("photo.jpg", return_bytes=True, target_encoding='utf-8')

Notes:
- pytesseract requires the Tesseract executable installed on the system (separate from the Python package). If pytesseract is not installed, the function will still work but will only use metadata/comments as a fallback.
- chardet is used to guess encodings of raw bytes when necessary. This function attempts several likely encodings first (utf-8, utf-16, cp1252, latin1) before using chardet and finally falling back to latin1.
- The function aims to be robust across JPEG/PNG metadata conventions (EXIF UserComment, XP* tags, JPEG comments, PNG tEXt).

def format_unix_timestamp(ts, tz='UTC', fmt='%Y-%m-%d %H:%M:%S %Z%z'):
    """
    Convert a Unix timestamp (seconds since epoch) to a formatted date/time string in a specified timezone.
    Uses the standard library zoneinfo when available (Python 3.9+). Falls back to pytz if zoneinfo isn't present.
    Accepts:
      - ts: int or float Unix timestamp (seconds). If a very large number (>= 1e12), it's treated as milliseconds.
      - tz: timezone name (e.g., 'UTC', 'Europe/Berlin'), an offset string like '+02:00' or a tzinfo object.
      - fmt: strftime format string (default: 'YYYY-MM-DD HH:MM:SS TZ offset').
    Returns:
      - formatted date/time string.
    Raises:
      - TypeError if ts is not numeric.
      - ValueError if the timezone name is invalid or required libraries are missing.
    Example:
      format_unix_timestamp(1625072400, 'Europe/Berlin') -> '2021-06-30 15:00:00 CEST+0200'
    """
    import datetime

    # Validate/normalize timestamp
    try:
        ts = float(ts)
    except Exception:
        raise TypeError("ts must be a number (seconds since the Unix epoch)")

    # Treat very large values as milliseconds
    if abs(ts) >= 1e12:
        ts = ts / 1000.0

    # Helper to parse offset strings like "+02:00" or "-0500"
    def _offset_tz(offset_str):
        # supports +HH:MM, +HHMM, +HH
        s = offset_str
        sign = 1 if s[0] == '+' else -1
        s = s[1:]
        if ':' in s:
            hh, mm = s.split(':', 1)
        elif len(s) in (3, 4):
            hh, mm = s[:-2], s[-2:]
        else:
            hh, mm = s, '0'
        try:
            offset_seconds = sign * (int(hh) * 3600 + int(mm) * 60)
        except ValueError:
            raise ValueError(f"Invalid offset format: {offset_str}")
        return datetime.timezone(datetime.timedelta(seconds=offset_seconds))

    # Attempt to use zoneinfo (stdlib)
    using_pytz = False
    ZoneInfo = None
    try:
        from zoneinfo import ZoneInfo  # Python 3.9+
    except Exception:
        ZoneInfo = None
        # Try pytz fallback
        try:
            import pytz
            using_pytz = True
        except Exception:
            pytz = None

    # Build tzinfo object
    tzinfo = None
    if isinstance(tz, datetime.tzinfo):
        tzinfo = tz
    elif isinstance(tz, str) and (tz.startswith('+') or tz.startswith('-')):
        tzinfo = _offset_tz(tz)
    else:
        # tz is a string name
        if ZoneInfo is not None:
            try:
                tzinfo = ZoneInfo(tz)
            except Exception as e:
                raise ValueError(f"Invalid timezone name for zoneinfo: {tz!r}: {e}")
        elif using_pytz:
            try:
                tzinfo = pytz.timezone(tz)
            except Exception as e:
                raise ValueError(f"Invalid timezone name for pytz: {tz!r}: {e}")
        else:
            raise ValueError(
                "No timezone support available: install Python 3.9+ (zoneinfo) or pytz, "
                "or pass a tzinfo object."
            )

    # Create aware datetime in target timezone
    if using_pytz:
        # Use UTC base then convert (safe for pytz)
        try:
            dt = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc).astimezone(tzinfo)
        except Exception as e:
            raise ValueError(f"Error converting timestamp with pytz timezone: {e}")
    else:
        try:
            # zoneinfo and datetime.timezone tzinfo support direct fromtimestamp with tz param
            dt = datetime.datetime.fromtimestamp(ts, tz=tzinfo)
        except Exception as e:
            # fallback: build UTC then astimezone
            try:
                dt = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc).astimezone(tzinfo)
            except Exception as e2:
                raise ValueError(f"Error converting timestamp to timezone: {e2}") from e

    return dt.strftime(fmt)


