Here's a single self-contained Python function that extracts the first URL from a string, fetches the page (with a small download cap), and returns the page title or an informative error. It uses the lightweight requests library (pip install requests). The function returns a dict: {'success': True, 'title': ...} on success or {'success': False, 'error': ...} on failure.

```python
import re
import requests
import html

def get_url_title(text, max_bytes=100*1024, timeout=10):
    """
    Extract the first URL from `text`, fetch the page (up to `max_bytes` bytes),
    and return the page <title>.

    Returns:
      {'success': True, 'title': '...'} on success
      {'success': False, 'error': '...'} on failure

    Requires: requests (pip install requests)
    """
    # 1) Find a URL-like substring
    # This matches http(s)://..., www.... or bare domain.tld...
    url_match = re.search(
        r'(https?://[^\s<>"]+|www\.[^\s<>"]+|[A-Za-z0-9.-]+\.[A-Za-z]{2,6}[^\s<>"]*)',
        text,
        re.IGNORECASE,
    )
    if not url_match:
        return {'success': False, 'error': 'No valid URL found in input text.'}

    url = url_match.group(0).strip('\'"()[]<>.,;:')

    # Ensure scheme
    if not url.lower().startswith(('http://', 'https://')):
        url = 'http://' + url

    try:
        headers = {'User-Agent': 'title-extractor/1.0 (+https://example)'}
        resp = requests.get(url, headers=headers, stream=True, timeout=timeout, allow_redirects=True)

        if resp.status_code >= 400:
            return {'success': False, 'error': f'HTTP error {resp.status_code} while fetching URL.'}

        # Read up to max_bytes to avoid downloading huge pages
        content_bytes = bytearray()
        for chunk in resp.iter_content(chunk_size=1024):
            if chunk:
                content_bytes.extend(chunk)
            if len(content_bytes) >= max_bytes:
                break

        # Determine encoding: prefer response.encoding if provided
        encoding = resp.encoding or 'utf-8'
        try:
            html_text = content_bytes.decode(encoding, errors='replace')
        except Exception:
            html_text = content_bytes.decode('utf-8', errors='replace')

        # Extract <title>...</title>
        m = re.search(r'<title[^>]*>(.*?)</title>', html_text, re.IGNORECASE | re.DOTALL)
        if not m:
            return {'success': False, 'error': 'No <title> tag found in page.'}

        title = m.group(1).strip()
        # Normalize whitespace and unescape entities
        title = re.sub(r'\s+', ' ', html.unescape(title)).strip()
        if not title:
            return {'success': False, 'error': 'Title tag is empty.'}

        return {'success': True, 'title': title}

    except requests.exceptions.RequestException as e:
        return {'success': False, 'error': f'Error fetching URL: {e}'}
```

Example:
- get_url_title("Check this out: https://www.python.org") -> {'success': True, 'title': 'Welcome to Python.org'}

```python
from typing import List, Optional
import requests
import datetime

def get_repo_names_sorted_by_creation(username: str, token: Optional[str] = None) -> List[str]:
    """
    Retrieve the repository names of a GitHub user, sorted ascending by creation date (oldest first).

    Parameters:
    - username: GitHub username (str)
    - token: optional GitHub personal access token (str). Using a token increases rate limits.

    Returns:
    - List of repository names sorted by their creation date (oldest -> newest).

    Raises:
    - ValueError if the user is not found.
    - RuntimeError for other HTTP errors or unexpected responses.
    """
    def _parse_created_at(s: Optional[str]) -> datetime.datetime:
        # GitHub returns e.g. "2011-01-26T19:06:43Z". Replace Z with +00:00 for fromisoformat.
        if not s:
            return datetime.datetime.min
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(s)

    base_url = f"https://api.github.com/users/{username}/repos"
    headers = {}
    if token:
        headers["Authorization"] = f"token {token}"

    per_page = 100
    page = 1
    repos = []

    while True:
        params = {"per_page": per_page, "page": page}
        try:
            resp = requests.get(base_url, headers=headers, params=params, timeout=10)
        except requests.RequestException as e:
            raise RuntimeError(f"Network error while contacting GitHub API: {e}") from e

        if resp.status_code == 404:
            raise ValueError(f"GitHub user '{username}' not found (404).")
        if resp.status_code != 200:
            # Try to include any message from the API
            msg = ""
            try:
                msg = resp.json().get("message", "")
            except Exception:
                pass
            raise RuntimeError(f"GitHub API error {resp.status_code}: {msg}")

        try:
            page_data = resp.json()
        except ValueError as e:
            raise RuntimeError("Invalid JSON response from GitHub API.") from e

        if not isinstance(page_data, list):
            raise RuntimeError("Unexpected response structure from GitHub API.")

        if not page_data:
            break

        for item in page_data:
            name = item.get("name")
            created_at = _parse_created_at(item.get("created_at"))
            if name is not None:
                repos.append((name, created_at))

        # If fewer than per_page results returned, no more pages
        if len(page_data) < per_page:
            break
        page += 1

    # Sort by creation datetime ascending and return names
    repos.sort(key=lambda tup: tup[1])
    return [name for name, _ in repos]
```

Example usage:
- get_repo_names_sorted_by_creation("octocat")
- get_repo_names_sorted_by_creation("octocat", token="ghp_....")
